result.output:
"""リリース計画 Issue の順番の表の読み取りと、「今のリリース」と「次のリリース」の判定 (計画の R36・U2)。

表の書式と判定の規則の SSOT は、文書 `issue-practice/references/release-plan-table.md` とこのモジュール。
テスト (ファイル `issue-practice/tests/test_releaseplan.py`) が、文書の見出しの行と定数が一致することを確認する。

関数は、解析できた値の辞書か、理由を持つ辞書を返す。例外は送出しない。gh が失敗したときは、失敗した gh の結果を返す。
"""

import re

from issue_practice import bodies, gh, records, refs

SECTION_TITLE = "リリースの順番"
HEADER = ("順", "リリース Issue", "主題")
CURRENT_LABEL = "current"
TARGET_LABEL_PREFIX = "release-target:"
DRAFT_MARK = "[DRAFT]"

_ROW_RE = re.compile(r"^\s*\|(?P<cells>.*)\|\s*$")
_DELIMITER_RE = re.compile(r"^\s*:?-{3,}:?\s*$")
_ORDER_RE = re.compile(r"^[1-9][0-9]*$")
_ISSUE_RE = re.compile(r"^#(?P<number>[1-9][0-9]*)$")


def _cells(line):
    m = _ROW_RE.match(line.rstrip("\r"))
    if not m:
        return None
    return [cell.strip() for cell in m.group("cells").split("|")]


def parse_table(body):
    """本文の節「リリースの順番」の表を読む。

    返り値は {"rows": [{"order", "number", "subject", "line"}]} か {"errors": [<理由>]}。行番号は本文の 1 行目を 1 とする。
    """
    section = bodies.find_section(body, SECTION_TITLE)
    if "error" in section:
        return {"errors": [section["error"]]}
    lines = section["lines"]
    visible = bodies.outside_fences([text for _, text in lines])
    table_lines = [(number, text) for i, (number, text) in enumerate(lines) if i in visible and _cells(text) is not None]
    if not table_lines:
        return {"errors": [f"節「{SECTION_TITLE}」に表が無い"]}
    # 表は、連続した表の行の 1 つのまとまり。まとまりが 2 つ以上あれば誤り
    groups, previous = [], None
    for number, text in table_lines:
        if previous is None or number != previous + 1:
            groups.append([])
        groups[-1].append((number, text))
        previous = number
    if len(groups) > 1:
        return {"errors": [f"節「{SECTION_TITLE}」に表が複数ある (行 {', '.join(str(g[0][0]) for g in groups)})"]}
    table = groups[0]
    header_line, header = table[0][0], _cells(table[0][1])
    if tuple(header) != HEADER:
        return {"errors": [f"行 {header_line}: 表の見出しの行が「| {' | '.join(HEADER)} |」ではない"]}
    if len(table) < 2 or not all(_DELIMITER_RE.match(c) for c in _cells(table[1][1])) or len(_cells(table[1][1])) != len(HEADER):
        return {"errors": [f"行 {header_line + 1}: 表の見出しの行の次が、区切りの行 (| --- | --- | --- |) ではない"]}
    rows, errors, seen = [], [], {}
    for number, text in table[2:]:
        cells = _cells(text)
        if len(cells) != len(HEADER):
            errors.append(f"行 {number}: 列の数が {len(HEADER)} ではない")
            continue
        order, issue, subject = cells
        if not _ORDER_RE.match(order):
            errors.append(f"行 {number}: 列「順」が 1 以上の整数ではない: {order!r}")
            continue
        m = _ISSUE_RE.match(issue)
        if not m:
            errors.append(f"行 {number}: 列「リリース Issue」が #<番号> の形ではない: {issue!r}")
            continue
        if not subject:
            errors.append(f"行 {number}: 列「主題」が空")
            continue
        issue_number = int(m.group("number"))
        if issue_number in seen:
            errors.append(f"行 {number}: リリース Issue #{issue_number} が 2 回ある (行 {seen[issue_number]})")
            continue
        seen[issue_number] = number
        rows.append({"order": int(order), "number": issue_number, "subject": subject, "line": number})
    if not errors and not rows:
        errors.append(f"節「{SECTION_TITLE}」の表に行が無い")
    if not errors:
        for expected, row in enumerate(rows, start=1):
            if row["order"] != expected:
                errors.append(f"行 {row['line']}: 列「順」が 1 から始まる連番になっていない ({expected} のところが {row['order']})")
                break
    if errors:
        return {"errors": errors}
    return {"rows": rows}


def choose_plan(plans):
    """ラベル current の付いた開いている計画の配列 ({"number", "created_at", ...}) から、表を読む計画を選ぶ。

    返り値は {"plan" (計画が無ければ None), "swapping" (付け替えの途中か)} か {"error"}。
    """
    if not plans:
        return {"plan": None, "swapping": False}
    if len(plans) == 1:
        return {"plan": plans[0], "swapping": False}
    if len(plans) == 2:
        return {"plan": max(plans, key=lambda p: (p["created_at"] or "", p["number"])), "swapping": True}
    numbers = ", ".join(f"#{p['number']}" for p in plans)
    return {"error": f"ラベル {CURRENT_LABEL} の付いたリリース計画 Issue が {len(plans)} つある ({numbers})。"
                     "付け替えの途中でも 2 つまでなので、決めた形が崩れている"}


def is_draft(title):
    return DRAFT_MARK in (title or "")


def decide(rows, lookup):
    """表の行から「今」と「次」を決める (計画の R36)。

    lookup はリリース Issue の番号を受け取り、({"number", "url", "state", "title", "body"}, None) か (None, 失敗した gh の結果) を
    返す関数。表のすべての行のリリース Issue を読む。
    返り値は {"current", "next", "gh_error", "errors"}。current と next は {"order", "number", "subject", "line", "issue"} か None。
    """
    open_entries = []
    for row in rows:
        issue, failure = lookup(row["number"])
        if failure:
            return {"current": None, "next": None, "gh_error": failure, "errors": []}
        if "/pull/" in (issue.get("url") or ""):
            return {"current": None, "next": None, "gh_error": None,
                    "errors": [f"表の行 {row['line']} の #{row['number']} は PR で、リリース Issue ではない"]}
        if issue["state"] == "OPEN":
            open_entries.append({**row, "issue": issue})
    current = next((e for e in open_entries if not is_draft(e["issue"]["title"])), None)
    if current is None:
        following = open_entries[0] if open_entries else None
    else:
        following = next((e for e in open_entries if e["order"] > current["order"]), None)
    return {"current": current, "next": following, "gh_error": None, "errors": []}


def find_milestone(milestones, number, target):
    """リリース Issue の番号とリリース対象から、リリースマイルストーンを探す。

    milestones は REST の milestone の配列。返り値は {"milestone"} か {"error"}。
    """
    found = []
    for milestone in milestones:
        parsed = refs.parse_milestone_name(milestone.get("title"))
        if "error" in parsed or parsed["number"] != number or parsed["target"] != target:
            continue
        found.append(milestone)
    if not found:
        return {"error": f"リリース Issue #{number} のリリースマイルストーン (R{number} "
                         f"{target + ' ' if target else ''}(主題)) が無いか、閉じている"}
    if len(found) > 1:
        return {"error": f"リリース Issue #{number} のリリースマイルストーンが複数ある "
                         f"({', '.join(repr(m.get('title')) for m in found)})"}
    return {"milestone": found[0]}


def check_links(issue, milestone):
    """リリース Issue とリリースマイルストーンが、お互いの URL を持つか。誤りの配列を返す。"""
    errors = []
    if issue["url"] not in (milestone.get("description") or ""):
        errors.append(f"マイルストーン {milestone.get('title')!r} の説明に、リリース Issue の URL ({issue['url']}) が無い")
    if (milestone.get("html_url") or "") not in (issue.get("body") or "") or not milestone.get("html_url"):
        errors.append(f"リリース Issue #{issue['number']} の本文に、マイルストーンの URL ({milestone.get('html_url')}) が無い")
    return errors


# --- GitHub から読む -------------------------------------------------------------------------------------------

def fetch_targets(repo):
    """リポジトリのラベル release-target:<名前> から、リリース対象の名前の配列を返す。返り値は (名前の配列, None) か (None, 失敗)。"""
    result = gh.run(["label", "list", "-R", repo, "--json", "name", "--limit", "1000"], expect_json=True)
    if gh.failed(result):
        return None, result
    data = result["json"]
    if not isinstance(data, list):
        return None, {**result, "json_error": "応答がラベルの配列ではない"}
    names = [label.get("name") for label in data if isinstance(label, dict)]
    return sorted(n[len(TARGET_LABEL_PREFIX):] for n in names if isinstance(n, str) and n.startswith(TARGET_LABEL_PREFIX)), None


def fetch_plans(repo, target):
    """ラベル current (とリリース対象のラベル) の付いた開いている Issue を返す。返り値は (計画の配列, None) か (None, 失敗)。"""
    args = ["issue", "list", "-R", repo, "--state", "open", "--label", CURRENT_LABEL]
    if target:
        args += ["--label", TARGET_LABEL_PREFIX + target]
    args += ["--json", "number,url,title,body,createdAt", "--limit", "100"]
    result = gh.run(args, expect_json=True)
    if gh.failed(result):
        return None, result
    data = result["json"]
    if not isinstance(data, list):
        return None, {**result, "json_error": "応答が Issue の配列ではない"}
    return [{"number": d.get("number"), "url": d.get("url"), "title": d.get("title"), "body": d.get("body") or "",
             "created_at": d.get("createdAt")} for d in data if isinstance(d, dict)], None


def fetch_release_issue(repo, number):
    result = gh.run(["issue", "view", str(number), "-R", repo, "--json", "number,url,state,title,body"], expect_json=True)
    if gh.failed(result):
        return None, result
    data = result["json"]
    if not isinstance(data, dict):
        return None, {**result, "json_error": "応答が Issue のオブジェクトではない"}
    return {"number": data.get("number"), "url": data.get("url"), "state": data.get("state"), "title": data.get("title"),
            "body": data.get("body") or ""}, None


def fetch_open_milestones(repo):
    result = gh.run(["api", f"repos/{repo}/milestones?state=open&per_page=100", "--paginate", "--slurp"], expect_json=True)
    if gh.failed(result):
        return None, result
    pages = result["json"]
    if not isinstance(pages, list) or not all(isinstance(p, list) for p in pages):
        return None, {**result, "json_error": "応答がページの配列 (--slurp の形) ではない"}
    return [m for page in pages for m in page if isinstance(m, dict)], None


def _release_output(entry, milestone, running):
    issue = entry["issue"]
    return {"order": entry["order"], "number": issue["number"], "url": issue["url"], "title": issue["title"],
            "subject": entry["subject"], "draft": is_draft(issue["title"]), "running": running,
            "milestone": {"number": milestone.get("number"), "title": milestone.get("title"), "url": milestone.get("html_url")},
            "selectable": True, "reason": None}


def current_and_next(repo, target=None, carve_out=False):
    """リポジトリ repo (owner/repo) の「今」と「次」を決める。

    返り値は {"status": "ok" | "unsatisfied" | "gh_failed", ...}。ok と unsatisfied では {"target", "targets", "plan",
    "swapping", "current", "next", "errors"}、gh_failed では {"gh_error"} を持つ。
    """
    out = {"repo": repo, "target": target, "targets": [], "plan": None, "swapping": False, "current": None, "next": None,
           "errors": []}

    def failed(failure):
        return {**out, "status": "gh_failed", "gh_error": failure}

    def unsatisfied(*errors):
        out["errors"] += list(errors)
        return {**out, "status": "unsatisfied"}

    targets, failure = fetch_targets(repo)
    if failure:
        return failed(failure)
    out["targets"] = targets
    if targets and not target:
        return unsatisfied(f"リリース対象が複数ある ({', '.join(targets)})。--target でどのリリース対象かを指定する")
    if target and target not in targets:
        return unsatisfied(f"リリース対象 {target!r} のラベル {TARGET_LABEL_PREFIX}{target} が無い")
    plans, failure = fetch_plans(repo, target)
    if failure:
        return failed(failure)
    chosen = choose_plan(plans)
    if "error" in chosen:
        return unsatisfied(chosen["error"])
    out["swapping"] = chosen["swapping"]
    plan = chosen["plan"]
    if plan is None:
        return {**out, "status": "ok"}
    out["plan"] = {"number": plan["number"], "url": plan["url"], "title": plan["title"], "created_at": plan["created_at"]}
    table = parse_table(plan["body"])
    if "errors" in table:
        return unsatisfied(*(f"リリース計画 Issue #{plan['number']} の{e}" if not e.startswith("行 ")
                             else f"リリース計画 Issue #{plan['number']} の本文の{e}" for e in table["errors"]))
    decided = decide(table["rows"], lambda number: fetch_release_issue(repo, number))
    if decided["gh_error"]:
        return failed(decided["gh_error"])
    if decided["errors"]:
        return unsatisfied(*decided["errors"])
    if decided["current"] is None and decided["next"] is None:
        return {**out, "status": "ok"}
    milestones, failure = fetch_open_milestones(repo)
    if failure:
        return failed(failure)
    errors = []
    for name in ("current", "next"):
        entry = decided[name]
        if entry is None:
            continue
        found = find_milestone(milestones, entry["number"], target)
        if "error" in found:
            errors.append(found["error"])
            continue
        errors += check_links(entry["issue"], found["milestone"])
        running = False
        if name == "current":
            ref = refs.parse_ref(entry["issue"]["url"])
            listed, failure = records.list_records(ref)
            if failure:
                return failed(failure)
            if listed["invalid"]:
                errors.append(f"リリース Issue #{entry['number']} に、1 行目の形が違う記録のコメントがある "
                              f"({', '.join(i['url'] or '' for i in listed['invalid'])})")
            kinds = {r["kind"] for r in listed["records"]}
            if "draft-removed" not in kinds:
                errors.append(f"リリース Issue #{entry['number']} は題名に {DRAFT_MARK} が無いのに、"
                              "記録のコメント draft-removed が無い")
            running = "release-start" in kinds
        out[name] = _release_output(entry, found["milestone"], running)
    if errors:
        out["current"], out["next"] = None, None
        return unsatisfied(*errors)
    if carve_out and out["current"] and out["current"]["running"]:
        out["current"]["selectable"] = False
        out["current"]["reason"] = "リリースの実行中に切り出すときは、今のリリースを選べない (計画の R13)"
    return {**out, "status": "ok"}
"""`gh` の実行。このモジュールの関数 `run` だけが `gh` を起動する (計画の KTD11)。ほかのモジュールは `subprocess` で `gh` を
呼ばず、`run` に引数の配列を渡す。

プラグイン issue-dispatch のファイル `issue-dispatch/scripts/issue_dispatch/gh.py` をコピーし、issue-practice で使わない関数
(レート制限の再開時刻を読む関数) を除いて、トークンのログインを読む関数 `viewer_login` を足したもの。プラグインは別々に
配布するので、ファイルは共有しない。

`run` は、終了コード・標準出力・標準エラー出力の末尾・タイムアウトで打ち切ったか・失敗の種類 (`failure`) を返す。
失敗の種類は標準エラー出力と標準出力の文言から分け、再試行はしない。失敗したときの終了コード (計画の KTD10 の 4) は
呼び出し元 (CLI の入口) が決める。

テストは PATH の先頭に偽の `gh` (ファイル `issue-practice/tests/fake-gh`) のディレクトリを加えて差し替える。
"""

import json
import re
import subprocess
import time

DEFAULT_TIMEOUT = 60
STDERR_TAIL_LINES = 20
MUTATION_INTERVAL = 1.0  # 変更系の呼び出しの後に待機する秒数 (次の変更系の呼び出しと 1 秒以上空ける)

# 失敗の種類。None は成功。`missing` は gh が PATH に無いか実行権限が無い (入れる・権限を直すのが直し方)
FAILURES = ("auth", "rate_limit", "network", "timeout", "missing", "other")

_AUTH_RE = re.compile(r"HTTP 401|Bad credentials|gh auth login|not logged in", re.IGNORECASE)
_RATE_LIMIT_RE = re.compile(r"rate limit|RATE_LIMITED|secondary rate|abuse detection", re.IGNORECASE)
_NETWORK_RE = re.compile(
    r"dial tcp|connection refused|connection reset|no such host|i/o timeout|TLS handshake|proxyconnect|"
    r"network is unreachable|error connecting|could not resolve host",
    re.IGNORECASE,
)


def _graphql_error_types(stdout):
    """標準出力が GraphQL の応答なら、トップレベルの errors[].type の集合。読めなければ空。"""
    try:
        data = json.loads(stdout)
    except ValueError:
        return set()
    errors = data.get("errors") if isinstance(data, dict) else None
    if not isinstance(errors, list):
        return set()  # errors が無い・null・配列でない応答
    return {e.get("type") for e in errors if isinstance(e, dict)}


def classify(exit_code, stdout, stderr, timed_out):
    """終了コードと出力から失敗の種類を決める。成功 (終了コード 0) なら None。

    文言を見るのは `gh` 自身が書く標準エラー出力だけ。標準出力 (API の応答) には Issue の本文など利用者の書いた
    文字列が入るので、正規表現では見ず、JSON として読めたときのトップレベルの errors[].type だけを見る。
    """
    if timed_out:
        return "timeout"
    if exit_code == 0:
        return None
    if _AUTH_RE.search(stderr):
        return "auth"
    if _RATE_LIMIT_RE.search(stderr) or "RATE_LIMITED" in _graphql_error_types(stdout):
        return "rate_limit"
    if _NETWORK_RE.search(stderr):
        return "network"
    return "other"


def _tail(text, lines=STDERR_TAIL_LINES):
    return "\n".join(text.splitlines()[-lines:])


def _text(value):
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value


def run(args, timeout=DEFAULT_TIMEOUT, mutation=False, expect_json=False, stdin=None):
    """`gh` を引数の配列で実行する。

    mutation が真なら、gh が終了した後に MUTATION_INTERVAL 秒待機してから返る。次の変更系の呼び出しがこのプロセスでも
    別のプロセス (CLI はサブコマンドごとに 1 プロセス) でも、1 秒以上空く。
    返り値: {"args", "exit_code" (タイムアウトと起動できなかったときは None), "stdout", "stderr_tail", "timed_out",
    "failure", "json" (標準出力が JSON として読めればその値、読めなければ None), "json_error" (expect_json が真で、
    標準出力が空でないのに JSON として読めなかったときの理由。それ以外は None)}

    stdin は、標準入力に渡す文字列 (`gh api graphql --input -` の本文など)。None なら標準入力は渡さない (/dev/null)。
    expect_json は、呼び出し元が標準出力に JSON を期待するときに真を渡す (`gh api` や `--json` で JSON を受け取る
    呼び出し)。引数から推測しない。`--jq` や `--template` で文字列を取り出す呼び出しや、URL や文章を出すコマンド
    (`gh issue comment` など) では渡さない。

    `gh api --paginate` は、ページごとの JSON をつないで出すので 1 つの JSON として読めない。`--slurp` と一緒に使い、
    全ページを 1 つの配列で受け取る。
    """
    args = list(args)
    try:
        completed = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=timeout,
                                   input=stdin, stdin=subprocess.DEVNULL if stdin is None else None)
        exit_code, stdout, stderr, timed_out = completed.returncode, completed.stdout, completed.stderr, False
    except subprocess.TimeoutExpired as e:
        exit_code, stdout, stderr, timed_out = None, _text(e.stdout), _text(e.stderr), True
    except OSError as e:
        # 起動できなかったことを返り値で伝える。gh が PATH に無い (FileNotFoundError)・実行権限が無い (PermissionError) は
        # `missing`。それ以外 (引数が長すぎる E2BIG など、gh が入っていても起きるもの) は `other`
        failure = "missing" if isinstance(e, (FileNotFoundError, PermissionError)) else "other"
        return {"args": args, "exit_code": None, "stdout": "", "stderr_tail": f"gh を起動できない: {e}",
                "timed_out": False, "failure": failure, "json": None, "json_error": None}
    finally:
        if mutation:
            time.sleep(MUTATION_INTERVAL)
    parsed, json_error = None, None
    if stdout.strip():
        try:
            parsed = json.loads(stdout)
        except ValueError as e:
            if expect_json:
                json_error = str(e)
    return {
        "args": args,
        "exit_code": exit_code,
        "stdout": stdout,
        "stderr_tail": _tail(stderr),
        "timed_out": timed_out,
        "failure": classify(exit_code, stdout, stderr, timed_out),
        "json": parsed,
        "json_error": json_error,
    }


def failed(result):
    """`run` の結果が、呼び出し元から見て失敗か (gh が失敗した・JSON を期待したのに読めなかった)。"""
    return result["failure"] is not None or result["json_error"] is not None


def describe_failure(result):
    """失敗した `run` の結果を、CLI の出力の `gh_error` に入れる形にする。"""
    return {"args": result["args"], "exit_code": result["exit_code"], "failure": result["failure"],
            "stderr_tail": result["stderr_tail"], "json_error": result["json_error"]}


def viewer_login(timeout=DEFAULT_TIMEOUT):
    """トークンのログイン (`gh api user` の `login`) を読む。返り値は (ログイン, 失敗した `run` の結果)。

    読めたときは (ログイン, None)、読めなかったときは (None, 結果)。応答に `login` が無いときも読めなかったとして扱う。
    """
    result = run(["api", "user"], timeout=timeout, expect_json=True)
    if failed(result):
        return None, result
    data = result["json"]
    login = data.get("login") if isinstance(data, dict) else None
    if not isinstance(login, str) or not login:
        return None, {**result, "json_error": "応答に login が無い"}
    return login, None

"""計画案の節「作る Issue」から Issue を作る。「示す」(plan) と「実行する」(create) の 2 つに分ける (計画の KTD3・KTD5・U2)。

節の書式とスキルが作るラベルの SSOT は、文書 `issue-practice/references/issue-bodies.md` とこのモジュールの定数。
テスト (ファイル `issue-practice/tests/test_issues.py`) が、文書の項目の名前とラベルの表が定数と一致することを確認する。

やり直し (計画の R7・KTD5): 作る Issue の本文の最後の行に `issue-practice: created-from draft=<ファイル名> key=<キー>` を書き、
「実行する」は同じ行を持つ開いた Issue を作り済みとして扱う。作り済みの Issue も、マイルストーン・ラベル・親 Issue・
blocked by を GitHub の今の状態と比べ、足りないものだけを設定する。今の状態が計画案と違えば、上書きせずに誤りにする
(`gh` は、別の親 Issue がある Issue に親を設定すると、エラーにせずに置き換えるため。固定データの README)。

関数は、解析できた値の辞書か、理由を持つ辞書を返す。例外は送出しない (計画案のファイルを開けないときの OSError を除く)。
"""

import os
import re

from issue_practice import bodies, draft, gh, records, refs, releaseplan

SECTION_TITLE = "作る Issue"
FIELDS = ("親 Issue", "依存先の Issue", "マイルストーン", "ラベル")
NONE_VALUE = "なし"
BODY_OPEN = "~~~markdown"
BODY_CLOSE = "~~~"
NO_RELEASE_LABEL = "no-release"

# スキルが作るラベル (計画の R9)。名前・色・説明
LABELS = {
    releaseplan.CURRENT_LABEL: ("0e8a16", "有効なリリース計画 Issue (issue-practice)"),
    NO_RELEASE_LABEL: ("cfd3d7", "どのリリースにも入れない Issue (issue-practice)"),
}
TARGET_LABEL_COLOR = "1d76db"
TARGET_LABEL_DESCRIPTION = "リリース対象 {name} のリリース計画 Issue とリリース Issue (issue-practice)"

_ITEM_RE = re.compile(r"^### (?P<key>[A-Za-z0-9][A-Za-z0-9._-]*): (?P<title>\S.*)$")
_FIELD_RE = re.compile(r"^- (?P<name>[^:]+): (?P<value>\S.*)$")
_TARGET_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")


def managed_label(name):
    """スキルが作るラベルなら (色, 説明)、そうでなければ None。"""
    if name in LABELS:
        return LABELS[name]
    if name.startswith(releaseplan.TARGET_LABEL_PREFIX):
        target = name[len(releaseplan.TARGET_LABEL_PREFIX):]
        if _TARGET_NAME_RE.match(target):
            return TARGET_LABEL_COLOR, TARGET_LABEL_DESCRIPTION.format(name=target)
    return None


def _split(value):
    return [v.strip() for v in value.split(",") if v.strip()]


def _parse_issue_ref(text, repo):
    ref = refs.parse_ref(text, default_repo=repo)
    if "error" in ref:
        return None, ref["error"]
    if ref["kind"] == "pull":
        return None, f"PR は書かない (本文の節「依存先」だけに書く): {text}"
    return ref, None


def parse_items(text, repo):
    """計画案の本文から節「作る Issue」を読む。repo は #番号 の参照を解決するリポジトリ (owner/repo)。

    返り値は {"items", "errors"}。items の要素は {"key", "title", "line", "parent", "blocked_by", "milestone", "labels",
    "body"} (parent と blocked_by の要素は refs.parse_ref の結果)。errors は {"line", "message"} の配列。
    """
    lines = [line.rstrip("\r") for line in bodies.split_lines(text)]
    visible = bodies.outside_fences(lines)
    level2 = [i for i in sorted(visible) if bodies.heading(lines[i]) and bodies.heading(lines[i])[0] == 2]
    starts = [i for i in level2 if bodies.heading(lines[i])[1] == SECTION_TITLE]
    errors, items = [], []
    if not starts:
        return {"items": [], "errors": [{"line": None, "message": f"節「{SECTION_TITLE}」(## {SECTION_TITLE}) が無い"}]}
    if len(starts) > 1:
        return {"items": [], "errors": [{"line": starts[1] + 1, "message": f"節「{SECTION_TITLE}」が複数ある"}]}
    start = starts[0]
    end = next((i for i in level2 if i > start), len(lines))
    item, i, seen = None, start + 1, {}

    def error(index, message):
        errors.append({"line": index + 1, "message": message})

    while i < end:
        line = lines[i]
        if not line.strip():
            i += 1
            continue
        m = _ITEM_RE.match(line)
        if m:
            if item is not None and item["body"] is None:
                error(item["line"] - 1, f"Issue {item['key']} の本文 ({BODY_OPEN} で囲んだ部分) が無い")
            key = m.group("key")
            if key in seen:
                error(i, f"キー {key} が 2 回ある (行 {seen[key]})")
            seen.setdefault(key, i + 1)
            item = {"key": key, "title": m.group("title").strip(), "line": i + 1, "fields": {}, "body": None}
            items.append(item)
            i += 1
            continue
        if item is None:
            error(i, "「### <キー>: <題名>」の見出しの前に、行がある")
            i += 1
            continue
        if line == BODY_OPEN:
            if item["body"] is not None:
                error(i, f"Issue {item['key']} の本文が 2 つある")
            close = next((j for j in range(i + 1, end) if lines[j].startswith(BODY_CLOSE)), None)
            if close is None or lines[close] != BODY_CLOSE:
                error(i, f"Issue {item['key']} の本文の囲みが閉じていない ({BODY_CLOSE} の行が無いか、"
                         f"本文の中に {BODY_CLOSE} で始まる行がある)")
                return {"items": [], "errors": errors}
            item["body"] = "\n".join(lines[i + 1:close])
            i = close + 1
            continue
        fm = _FIELD_RE.match(line)
        if fm and item["body"] is None:
            name = fm.group("name")
            if name not in FIELDS:
                error(i, f"知らない項目: {name!r} (項目: {'・'.join(FIELDS)})")
            elif name in item["fields"]:
                error(i, f"項目「{name}」が 2 回ある")
            else:
                expected = FIELDS[len(item["fields"])]
                if name != expected:
                    error(i, f"項目の順序が違う (ここは「{expected}」)")
                item["fields"][name] = (i, fm.group("value").strip())
            i += 1
            continue
        error(i, "項目 (- <項目>: <値>) か本文の囲み (~~~markdown) ではない行")
        i += 1
    if item is not None and item["body"] is None:
        error(item["line"] - 1, f"Issue {item['key']} の本文 ({BODY_OPEN} で囲んだ部分) が無い")
    if not items:
        error(start, f"節「{SECTION_TITLE}」に Issue が無い")

    parsed = []
    for item in items:
        missing = [name for name in FIELDS if name not in item["fields"]]
        if missing:
            error(item["line"] - 1, f"Issue {item['key']} に項目が無い: {'・'.join(missing)} (値が無ければ「なし」と書く)")
            continue
        out = {"key": item["key"], "title": item["title"], "line": item["line"], "parent": None, "blocked_by": [],
               "milestone": None, "labels": [], "body": item["body"]}
        index, value = item["fields"]["親 Issue"]
        if value != NONE_VALUE:
            ref, problem = _parse_issue_ref(value, repo)
            if problem:
                error(index, f"親 Issue: {problem}")
            else:
                out["parent"] = ref
        index, value = item["fields"]["依存先の Issue"]
        if value != NONE_VALUE:
            keys = set()
            for text_ref in _split(value):
                ref, problem = _parse_issue_ref(text_ref, repo)
                if problem:
                    error(index, f"依存先の Issue: {problem}")
                elif ref["key"].lower() in keys:
                    error(index, f"依存先の Issue に {ref['key']} が 2 回ある")
                else:
                    keys.add(ref["key"].lower())
                    out["blocked_by"].append(ref)
        index, value = item["fields"]["マイルストーン"]
        if value != NONE_VALUE:
            out["milestone"] = value
        index, value = item["fields"]["ラベル"]
        if value != NONE_VALUE:
            out["labels"] = _split(value)
            if len({label.lower() for label in out["labels"]}) != len(out["labels"]):
                error(index, "同じラベルが 2 回ある")
        if out["milestone"] and NO_RELEASE_LABEL in out["labels"]:
            error(index, f"マイルストーンとラベル {NO_RELEASE_LABEL} の両方がある")
        parsed.append(out)
    errors.sort(key=lambda e: (e["line"] is not None, e["line"] or 0))
    return {"items": parsed, "errors": errors}


def read(path, repo):
    """計画案のファイルを読み、先頭の書式 (draft.parse) と節「作る Issue」を解析する。

    返り値は {"file_name", "items", "errors"}。ファイルを開けなければ OSError を送出する。
    """
    with open(path, encoding="utf-8") as f:
        text = f.read()
    name = os.path.basename(path)
    head = draft.parse(text, name)
    parsed = parse_items(text, repo)
    return {"file_name": name, "items": parsed["items"], "errors": head["errors"] + parsed["errors"]}


def created_from_line(file_name, key):
    return records.format_line("created-from", {"draft": file_name, "key": key}, where="body")["line"]


def created_from(body):
    """本文の最後の空でない行が created-from の行なら、その値 {"draft", "key"}。そうでなければ None。"""
    lines = [line.strip() for line in (body or "").splitlines() if line.strip()]
    if not lines:
        return None
    parsed = records.parse_line(lines[-1], where="body")
    if "errors" in parsed or parsed["kind"] != "created-from":
        return None
    return parsed["values"]


def issue_body(item, file_name):
    return item["body"].rstrip("\n") + "\n\n" + created_from_line(file_name, item["key"]) + "\n"


# --- GitHub から読む -------------------------------------------------------------------------------------------

def _json(result, check, message):
    if gh.failed(result):
        return None, result
    if not check(result["json"]):
        return None, {**result, "json_error": message}
    return result["json"], None


def fetch_labels(repo):
    data, failure = _json(gh.run(["label", "list", "-R", repo, "--json", "name", "--limit", "1000"], expect_json=True),
                          lambda d: isinstance(d, list), "応答がラベルの配列ではない")
    if failure:
        return None, failure
    return {label["name"].lower() for label in data if isinstance(label, dict) and isinstance(label.get("name"), str)}, None


def fetch_open_issues(repo):
    """開いている Issue (PR を除く) を全部読む。REST の issue の配列を返す。"""
    data, failure = _json(gh.run(["api", f"repos/{repo}/issues?state=open&per_page=100", "--paginate", "--slurp"],
                                 expect_json=True),
                          lambda d: isinstance(d, list) and all(isinstance(p, list) for p in d),
                          "応答がページの配列 (--slurp の形) ではない")
    if failure:
        return None, failure
    return [i for page in data for i in page if isinstance(i, dict) and "pull_request" not in i], None


def fetch_ref(ref):
    """参照先の Issue (か PR) の番号・URL・状態を読む。"""
    data, failure = _json(gh.run(["issue", "view", str(ref["number"]), "-R", f"{ref['owner']}/{ref['repo']}",
                                  "--json", "number,url,state,title"], expect_json=True),
                          lambda d: isinstance(d, dict) and isinstance(d.get("url"), str), "応答に url が無い")
    return data, failure


RELATION_FIELDS = "number,url,state,milestone,labels,parent,blockedBy"


def fetch_relations(url):
    """作り済みの Issue のマイルストーン・ラベル・親 Issue・blocked by を読む。"""
    data, failure = _json(gh.run(["issue", "view", url, "--json", RELATION_FIELDS], expect_json=True),
                          lambda d: isinstance(d, dict) and isinstance(d.get("url"), str), "応答に url が無い")
    if failure:
        return None, failure
    blocked = ((data.get("blockedBy") or {}).get("nodes")) or []
    return {"number": data.get("number"), "url": data["url"],
            "milestone": (data.get("milestone") or {}).get("title"),
            "labels": [label.get("name") for label in data.get("labels") or [] if isinstance(label, dict)],
            "parent": (data.get("parent") or {}).get("url"),
            "blocked_by": [node.get("url") for node in blocked if isinstance(node, dict)]}, None


def observe(repo, items):
    """計画案の Issue に関わる GitHub の今の状態を読む。返り値は (状態の辞書, None) か (None, 失敗した gh の結果)。"""
    labels, failure = fetch_labels(repo)
    if failure:
        return None, failure
    milestones, failure = releaseplan.fetch_open_milestones(repo)
    if failure:
        return None, failure
    referenced = {}
    for item in items:
        for ref in ([item["parent"]] if item["parent"] else []) + item["blocked_by"]:
            if ref["key"].lower() in referenced:
                continue
            data, failure = fetch_ref(ref)
            if failure:
                return None, failure
            referenced[ref["key"].lower()] = data
    open_issues, failure = fetch_open_issues(repo)
    if failure:
        return None, failure
    return {"labels": labels, "milestones": {m.get("title") for m in milestones}, "referenced": referenced,
            "open_issues": open_issues}, None


def _same_url(a, b):
    return (a or "").rstrip("/").lower() == (b or "").rstrip("/").lower()


def build(items, state, file_name):
    """「示す」の一覧を作る。返り値は ({"labels_to_create", "items", "errors"}, None) か (None, 失敗した gh の結果)。

    items の要素は {"key", "title", "line", "issue" (作り済みなら {"number", "url"}、無ければ None), "actions"}。
    作り済みの Issue があれば、その関係 (マイルストーン・ラベル・親 Issue・blocked by) を gh で読む。
    """
    errors, labels_to_create, out = [], [], []

    def error(item, message):
        errors.append({"line": item["line"], "message": f"Issue {item['key']}: {message}"})

    for item in items:
        if item["milestone"] and item["milestone"] not in state["milestones"]:
            error(item, f"マイルストーン {item['milestone']!r} が無いか、閉じている")
        for label in item["labels"]:
            if label.lower() in state["labels"] or any(label == l["name"] for l in labels_to_create):
                continue
            managed = managed_label(label)
            if managed is None:
                error(item, f"ラベル {label!r} がリポジトリに無い (スキルが作るラベルではないので、作らない)")
            else:
                labels_to_create.append({"name": label, "color": managed[0], "description": managed[1]})
        for role, ref in [("親 Issue", item["parent"])] + [("依存先の Issue", r) for r in item["blocked_by"]]:
            if ref is None:
                continue
            data = state["referenced"][ref["key"].lower()]
            if "/pull/" in data["url"]:
                error(item, f"{role} {ref['key']} は PR (blocked by と sub-issue は Issue どうしの関係)")
            elif data.get("state") != "OPEN":
                error(item, f"{role} {ref['key']} が閉じている")
            ref["url"] = data["url"]
        existing = [i for i in state["open_issues"]
                    if created_from(i.get("body")) == {"draft": file_name, "key": item["key"]}]
        entry = {"key": item["key"], "title": item["title"], "line": item["line"], "issue": None, "actions": []}
        out.append(entry)
        if len(existing) > 1:
            error(item, "同じ created-from の行を持つ開いた Issue が複数ある ("
                        + ", ".join(i.get("html_url") or "" for i in existing) + ")")
            continue
        parent_url = item["parent"]["url"] if item["parent"] else None
        blocker_urls = [ref["url"] for ref in item["blocked_by"]]
        if not existing:
            entry["actions"].append({"action": "create", "title": item["title"], "milestone": item["milestone"],
                                     "labels": item["labels"]})
            if parent_url:
                entry["actions"].append({"action": "set-parent", "parent": parent_url})
            if blocker_urls:
                entry["actions"].append({"action": "add-blocked-by", "issues": blocker_urls})
            continue
        found = existing[0]
        entry["issue"] = {"number": found.get("number"), "url": found.get("html_url")}
        now, failure = fetch_relations(found.get("html_url"))
        if failure:
            return None, failure
        if item["milestone"] and now["milestone"] != item["milestone"]:
            if now["milestone"]:
                error(item, f"作り済みの Issue に別のマイルストーン {now['milestone']!r} が設定されている (上書きしない)")
            else:
                entry["actions"].append({"action": "set-milestone", "milestone": item["milestone"]})
        missing_labels = [l for l in item["labels"] if l.lower() not in {n.lower() for n in now["labels"]}]
        if missing_labels:
            entry["actions"].append({"action": "add-labels", "labels": missing_labels})
        if parent_url and not _same_url(now["parent"], parent_url):
            if now["parent"]:
                error(item, f"作り済みの Issue に別の親 Issue {now['parent']} が設定されている (上書きしない)")
            else:
                entry["actions"].append({"action": "set-parent", "parent": parent_url})
        missing_blockers = [u for u in blocker_urls if not any(_same_url(u, b) for b in now["blocked_by"])]
        if missing_blockers:
            entry["actions"].append({"action": "add-blocked-by", "issues": missing_blockers})
    return {"labels_to_create": labels_to_create, "items": out, "errors": errors}, None


def plan(path, repo):
    """「示す」。返り値は {"status": "ok" | "unsatisfied" | "gh_failed", "draft", "repo", "labels_to_create", "items",
    "errors"} (gh_failed では "gh_error" も持つ)。"""
    parsed = read(path, repo)
    out = {"draft": parsed["file_name"], "repo": repo, "labels_to_create": [], "items": [], "errors": parsed["errors"]}
    if parsed["errors"]:
        return {**out, "status": "unsatisfied"}, parsed
    state, failure = observe(repo, parsed["items"])
    if failure:
        return {**out, "status": "gh_failed", "gh_error": failure}, parsed
    built, failure = build(parsed["items"], state, parsed["file_name"])
    if failure:
        return {**out, "status": "gh_failed", "gh_error": failure}, parsed
    out.update(built)
    return {**out, "status": "unsatisfied" if out["errors"] else "ok"}, parsed


# --- 書き込み -------------------------------------------------------------------------------------------------

APPROVAL_TEXT = "計画案 {file_name} を利用者が承認し、この Issue を作った。"


def _edit(url, *flags):
    return gh.run(["issue", "edit", url, *flags], mutation=True)


def _record_approval(url, file_name):
    """作った Issue に記録のコメント approval が無ければ書く。返り値は (書いたか, 失敗した gh の結果か None)。"""
    listed, failure = records.list_records(refs.parse_ref(url))
    if failure:
        return False, failure
    if any(r["kind"] == "approval" and r["values"].get("draft") == file_name for r in listed["records"]):
        return False, None
    line = records.format_line("approval", {"draft": file_name}, where="comment")["line"]
    result = gh.run(["issue", "comment", url, "--body-file", "-"], mutation=True,
                    stdin=f"{line}\n\n{APPROVAL_TEXT.format(file_name=file_name)}\n")
    if gh.failed(result):
        return False, result
    return True, None


def create(path, repo, record_approval=False):
    """「実行する」。「示す」と同じ一覧を作り、誤りが無ければ書き込む。

    返り値は「示す」の辞書に {"done" (行った書き込み {"key", "action", "url"} の配列), "issues" ({"key", "url"} の配列)}
    を足したもの。gh が失敗したら、そこで止めて status を gh_failed にし、それまでに行った書き込みを done に入れる。
    """
    result, parsed = plan(path, repo)
    result.update(done=[], issues=[])
    if result["status"] != "ok":
        return result
    done = result["done"]

    def failed(failure):
        return {**result, "status": "gh_failed", "gh_error": failure}

    for label in result["labels_to_create"]:
        r = gh.run(["label", "create", label["name"], "-R", repo, "--color", label["color"],
                    "--description", label["description"]], mutation=True)
        if gh.failed(r):
            return failed(r)
        done.append({"key": None, "action": "create-label", "url": None, "label": label["name"]})
    by_key = {item["key"]: item for item in parsed["items"]}
    for entry in result["items"]:
        item = by_key[entry["key"]]
        url = entry["issue"]["url"] if entry["issue"] else None
        for action in entry["actions"]:
            kind = action["action"]
            if kind == "create":
                args = ["issue", "create", "-R", repo, "--title", item["title"], "--body-file", "-"]
                if item["milestone"]:
                    args += ["--milestone", item["milestone"]]
                for label in item["labels"]:
                    args += ["--label", label]
                r = gh.run(args, mutation=True, stdin=issue_body(item, parsed["file_name"]))
                if gh.failed(r):
                    return failed(r)
                made = refs.parse_ref((r["stdout"].strip().splitlines() or [""])[-1])
                if "error" in made or made["kind"] != "issue":
                    return failed({**r, "json_error": "gh issue create の出力が Issue の URL ではない"})
                url = made["url"]
            elif kind == "set-milestone":
                r = _edit(url, "--milestone", action["milestone"])
            elif kind == "add-labels":
                r = _edit(url, *[flag for label in action["labels"] for flag in ("--add-label", label)])
            elif kind == "set-parent":
                r = _edit(url, "--parent", action["parent"])
            elif kind == "add-blocked-by":
                for blocker in action["issues"]:
                    r = _edit(url, "--add-blocked-by", blocker)
                    if gh.failed(r):
                        return failed(r)
            if gh.failed(r):
                return failed(r)
            done.append({"key": entry["key"], "action": kind, "url": url})
        if record_approval:
            wrote, failure = _record_approval(url, parsed["file_name"])
            if failure:
                return failed(failure)
            if wrote:
                done.append({"key": entry["key"], "action": "record-approval", "url": url})
        result["issues"].append({"key": entry["key"], "url": url})
    return result

"""管理 Issue (か自己管理 Issue) の計画案の解析と、計画案を GitHub に書く「示す」(plan) と「実行する」(apply)
(計画の U3・KTD3・KTD5・KTD7・KTD8・R6・R7・R19・R26・R49)。

計画案の書式の SSOT は、文書 `issue-practice/skills/managing-issue-plan/references/merge-plan.md` の節「管理 Issue の計画案」と
このモジュールの定数。テスト (ファイル `issue-practice/tests/test_managing.py`) が、文書の節の表と定数が一致することを確認する。

「実行する」は、次の順に書く。途中で失敗しても、同じ計画案でやり直せる (作り済みの作業 Issue は作らず、書いた本文は書かない)。
1. 節「作る Issue」の作業 Issue を作る (モジュール issues の create。作業 Issue ごとに approval の記録も書く)
2. PR マージ計画の表のキーを、作った作業 Issue の番号に置き換え、表から図を作る
3. 計画する Issue の本文の節「クローズ条件」と「PR マージ計画」を書き換える (本文が計画案を作ったときから変わっていれば書かない)
4. 計画する Issue に、記録のコメント approval を書く

関数は、結果の辞書を返す。例外は送出しない (計画案のファイルを開けないときの OSError を除く)。
"""

import os
import re

from issue_practice import bodies, closecheck, draft, gh, issues, mergeplan, records, refs

SECTIONS = ("対象", "クローズ条件", "PR マージ計画", "作る Issue")
TARGET_FIELDS = ("Issue", "種類")
KINDS = ("管理 Issue", "自己管理 Issue")
MANAGING, SELF_MANAGING = KINDS
CLOSING_SECTION = "クローズ条件"
MERGE_PLAN_SECTION = "PR マージ計画"
CLOSING_REGION = "closing-conditions"
APPROVAL_TEXT = "計画案 {file_name} を利用者が承認し、この Issue の節「クローズ条件」と「PR マージ計画」に書いた。"

_FIELD_RE = re.compile(r"^- (?P<name>[^:]+): (?P<value>\S.*)$")
_MARK_RE = re.compile(r"^\s*<!-- /?issue-practice:")


def _section(text, title):
    found = bodies.find_section(text, title)
    if "error" in found:
        return None
    return found


def _parse_target(section, sources, errors):
    fields = {}
    for number, line in section["lines"]:
        if not line.strip():
            continue
        m = _FIELD_RE.match(line)
        if not m or m.group("name") not in TARGET_FIELDS or m.group("name") in fields:
            errors.append({"line": number, "message": f"節「対象」の行は「- {TARGET_FIELDS[0]}: <URL>」と「- {TARGET_FIELDS[1]}: <種類>」"})
            continue
        fields[m.group("name")] = (number, m.group("value").strip())
    if set(fields) != set(TARGET_FIELDS):
        errors.append({"line": section["heading_line"], "message": f"節「対象」に「{TARGET_FIELDS[0]}」と「{TARGET_FIELDS[1]}」の両方を書く"})
        return None
    line, value = fields["Issue"]
    ref = refs.parse_ref(value)
    if "error" in ref or ref["kind"] != "issue":
        errors.append({"line": line, "message": f"項目「Issue」が Issue の URL ではない: {value!r}"})
        return None
    source = next((s for s in sources if refs.same_issue(refs.parse_ref(s["url"]), ref)), None)
    if source is None:
        errors.append({"line": line, "message": "項目「Issue」の Issue が、節「元にした Issue」に無い (本文のハッシュ値で照合するため)"})
        return None
    kind_line, kind = fields["種類"]
    if kind not in KINDS:
        errors.append({"line": kind_line, "message": f"項目「種類」は {'・'.join(KINDS)} のどちらか: {kind!r}"})
        return None
    return {"ref": ref, "url": ref["url"], "kind": kind, "sha256": source["sha256"]}


def parse(text, name, repo):
    """計画案の本文を解析する。name はファイル名、repo は #番号 の参照を解決するリポジトリ (owner/repo)。

    返り値は {"file_name", "target" ({"ref", "url", "kind", "sha256"} か None), "closing" (節「クローズ条件」の中身),
    "merge_plan" (mergeplan.parse の結果), "items" (節「作る Issue」の Issue。無ければ空), "errors"}。
    """
    head = draft.parse(text, name)
    errors = list(head["errors"])
    result = {"file_name": name, "target": None, "closing": None, "merge_plan": None, "items": [], "errors": errors}
    titles = tuple(s["title"] for s in head["sections"])
    if titles not in (SECTIONS[:3], SECTIONS):
        errors.append({"line": None, "message": "節「元にした Issue」の後に、節「" + "」「".join(SECTIONS[:3])
                       + "」(作業 Issue を作るときは、続けて「" + SECTIONS[3] + "」) をこの順に書く"})
        return result
    target = _parse_target(_section(text, "対象"), head["sources"], errors)
    result["target"] = target
    closing = _section(text, CLOSING_SECTION)
    result["closing"] = closing["content"]
    if not closing["content"].strip():
        errors.append({"line": closing["heading_line"], "message": "節「クローズ条件」が空"})
    for number, line in closing["lines"]:
        if _MARK_RE.match(line):
            errors.append({"line": number, "message": "節「クローズ条件」にマークを書かない (サブコマンドが書く)"})
    merge = _section(text, MERGE_PLAN_SECTION)
    plan = mergeplan.parse("\n".join(line for _, line in merge["lines"]), allow_keys=True, offset=merge["heading_line"])
    result["merge_plan"] = plan
    errors += plan["errors"]
    if SECTIONS[3] in titles:
        parsed = issues.parse_items(text, repo)
        result["items"] = parsed["items"]
        errors += parsed["errors"]
    if target is not None and not plan["errors"]:
        keys = {item["key"] for item in result["items"]}
        rows = plan["rows"]
        if target["kind"] == SELF_MANAGING:
            if result["items"]:
                errors.append({"line": None, "message": "自己管理 Issue の計画案には、節「作る Issue」を書かない"})
            if len(rows) != 1 or rows[0]["work"]["number"] != target["ref"]["number"] or plan["settings"]["config"] != "1":
                errors.append({"line": merge["heading_line"], "message": "自己管理 Issue の PR マージ計画は、ブランチの構成 1 で、"
                                                                      f"表の行はこの Issue (#{target['ref']['number']}) の 1 行だけ"})
        else:
            for row in rows:
                for item in [row["work"]] + row["requires"]:
                    if item["key"] is not None and item["key"] not in keys:
                        errors.append({"line": row["line"], "message": f"キー {item['key']} が、節「作る Issue」に無い"})
                if row["work"]["number"] == target["ref"]["number"]:
                    errors.append({"line": row["line"], "message": "管理 Issue 自身を、作業 Issue の行に書かない"})
    errors.sort(key=lambda e: (e["line"] is not None, e["line"] or 0))
    return result


def read(path, repo):
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return parse(text, os.path.basename(path), repo)


# --- 本文の書き換え ---------------------------------------------------------------------------------------------

def _marked(name, content):
    return f"{bodies.start_mark(name)}\n\n{content.strip(chr(10))}\n\n{bodies.end_mark(name)}"


def _replace_section(body, title, content):
    found = bodies.find_section(body, title)
    if "error" in found:
        # 節が無ければ (None, None) で、呼び出し元が本文の最後に足す。同じ見出しの節が複数あるときは誤り
        return None, None if found["error"].endswith("が無い") else found["error"]
    lines = bodies.split_lines(body)
    start, end = found["heading_line"] - 1, found["end_line"]
    inner = content.strip("\n").split("\n")
    if end < len(lines):
        new_lines = lines[:start + 1] + [""] + inner + [""] + lines[end:]
    else:
        new_lines = lines[:start + 1] + [""] + inner + [""]
    return "\n".join(new_lines), None


def _append_section(body, title, content):
    return body.rstrip("\n") + f"\n\n## {title}\n\n{content.strip(chr(10))}\n"


def _write_part(body, title, region, content):
    """region (マークの名前) があればマークの中を、無ければ見出しの節の中を書き換え、節も無ければ本文の最後に足す。

    region が None なら、マークを付けずに見出しの節に書く。返り値は {"body"} か {"error"}。
    """
    if region is not None and bodies.has_region_mark(body, region):
        return bodies.replace_region(body, region, content)
    text = _marked(region, content) if region is not None else content
    replaced, error = _replace_section(body, title, text)
    if error:
        return {"error": error}
    if replaced is not None:
        return {"body": replaced}
    return {"body": _append_section(body, title, text)}


def compose_checked(body, kind, closing, merge_content):
    """計画する Issue の本文に、クローズ条件と PR マージ計画 (マークの中身) を書いた本文を作る。

    管理 Issue はクローズ条件をマーク closing-conditions で囲み、自己管理 Issue はマークを付けずに節「クローズ条件」に書く。
    PR マージ計画は、どちらもマーク merge-plan で囲む。ほかの場所は変えない。返り値は {"body"} か {"error"}。
    """
    if kind == SELF_MANAGING and bodies.has_region_mark(body, CLOSING_REGION):
        return {"error": "自己管理 Issue の本文にマーク closing-conditions がある (自己管理 Issue の節「クローズ条件」にはマークを書かない)"}
    written = _write_part(body, CLOSING_SECTION, CLOSING_REGION if kind == MANAGING else None, closing)
    if "error" in written:
        return written
    return _write_part(written["body"], MERGE_PLAN_SECTION, mergeplan.REGION, merge_content)


def compose(body, kind, closing, merge_content):
    """compose_checked の本文。誤りのときは None。"""
    return compose_checked(body, kind, closing, merge_content).get("body")


# --- 示す・実行する ---------------------------------------------------------------------------------------------

def _empty_result(name, repo, errors):
    return {"status": "unsatisfied" if errors else "ok", "draft": name, "repo": repo, "target": None, "body_state": None,
            "issues": None, "merge_plan": None, "closing_conditions": None, "approval_recorded": None, "errors": errors}


def _plan(path, repo):
    """「示す」の本体。返り値は (結果の辞書, parse の結果, 作業 Issue の番号の辞書)。"""
    parsed = read(path, repo)
    name = parsed["file_name"]
    result = _empty_result(name, repo, list(parsed["errors"]))
    if parsed["errors"]:
        return result, parsed, {}
    target = parsed["target"]
    ref = target["ref"]
    result["target"] = {"issue": ref["key"], "url": target["url"], "kind": target["kind"]}
    result["closing_conditions"] = parsed["closing"]
    issue, failure = bodies.fetch_issue(ref)
    if failure:
        return {**result, "status": "gh_failed", "gh_error": failure}, parsed, {}
    meta, failure = closecheck.fetch_meta(ref)
    if failure:
        return {**result, "status": "gh_failed", "gh_error": failure}, parsed, {}
    milestone = (meta.get("milestone") or {}).get("title")
    for item in parsed["items"]:
        if item["milestone"] != milestone:
            result["errors"].append({"line": item["line"], "message": f"Issue {item['key']}: マイルストーン {item['milestone']!r} が、"
                                                                       f"計画する Issue のマイルストーン {milestone!r} と違う (R49)"})
    numbers = {}
    if parsed["items"]:
        shown, _ = issues.plan(path, repo)
        if shown["status"] == "gh_failed":
            return {**result, "status": "gh_failed", "gh_error": shown["gh_error"]}, parsed, {}
        result["issues"] = {k: shown[k] for k in ("labels_to_create", "items")}
        result["errors"] += shown["errors"]
        numbers = {i["key"]: i["issue"]["number"] for i in shown["items"] if i["issue"]}
    resolved = mergeplan.resolve(parsed["merge_plan"], numbers)
    unresolved = bool(resolved["errors"])
    preview = {**resolved, "errors": []}
    content = mergeplan.render(preview)
    result["merge_plan"] = {"settings": preview["settings"], "rows": mergeplan.rows_output(preview, ref["owner"], ref["repo"]),
                            "content": content}
    if issue["sha256"] == target["sha256"]:
        result["body_state"] = "pending"
        # 「実行する」は作業 Issue を作った後に本文を組み立てる。組み立てで見つかる誤り (同じ見出しの節が複数あるなど) は
        # 本文と計画案のクローズ条件だけで決まり、表の中身 (キーのままか番号か) によらないので、ここで見つけて作業 Issue を
        # 作る前に誤りとして返す (#278)
        composed = compose_checked(issue["body"], target["kind"], parsed["closing"], content)
        if "error" in composed:
            result["errors"].append({"line": None, "message": f"{ref['key']} の本文に書き込めない: {composed['error']}"})
    else:
        composed = None if unresolved else compose(issue["body"], target["kind"], parsed["closing"], content)
        result["body_state"] = "applied" if composed == issue["body"] else "changed"
    if result["body_state"] == "changed":
        result["errors"].append({"line": None, "message": f"{ref['key']} の本文が、計画案を作ったときから変わった (計画案を直す)"})
    listed, failure = records.list_records(ref)
    if failure:
        return {**result, "status": "gh_failed", "gh_error": failure}, parsed, numbers
    result["approval_recorded"] = any(r["kind"] == "approval" and r["values"].get("draft") == name for r in listed["records"])
    result["status"] = "unsatisfied" if result["errors"] else "ok"
    return result, parsed, numbers


def plan(path, repo):
    """「示す」。計画案と GitHub の今の状態から、書き込みの一覧を返す。GitHub には書き込まない。

    返り値は {"status", "draft", "repo", "target" ({"issue", "url", "kind"}), "body_state" (pending: これから書く・
    applied: 書き込み済み・changed: 計画案を作ったときから本文が変わった), "issues" (作業 Issue の「示す」の
    {"labels_to_create", "items"}。作らなければ null), "merge_plan" ({"settings", "rows", "content"}。content は本文に書く
    マークの中身で、作業 Issue を作る前はキーのまま), "closing_conditions", "approval_recorded", "errors"}。
    """
    return _plan(path, repo)[0]


def apply(path, repo):
    """「実行する」。plan と同じ確認をし、誤りが無ければ書き込む。返り値は plan の辞書に {"done"} を足したもの。

    done は行った書き込み {"key", "action", "url"} の配列 (action は issues create の action と、write-body・record-approval)。
    gh が失敗したら、そこで止めて status を gh_failed にし、それまでの書き込みを done に入れる。
    plan で誤りが見つかれば、何も書き込まずに status を unsatisfied にする。作業 Issue を作った後に、plan で読んだ後から
    計画する Issue の本文が変わったと分かったときも unsatisfied にし、それまでの書き込みを done に入れる。
    """
    result, parsed, numbers = _plan(path, repo)
    result["done"] = []
    if result["status"] != "ok":
        return result
    target = parsed["target"]
    ref = target["ref"]

    def failed(failure):
        return {**result, "status": "gh_failed", "gh_error": failure}

    if parsed["items"]:
        created = issues.create(path, repo, record_approval=True)
        result["done"] += created["done"]
        if created["status"] == "gh_failed":
            return failed(created["gh_error"])
        if created["status"] != "ok":
            result["errors"] += created["errors"]
            return {**result, "status": "unsatisfied"}
        numbers = {i["key"]: refs.parse_ref(i["url"])["number"] for i in created["issues"]}
    resolved = mergeplan.resolve(parsed["merge_plan"], numbers)
    if resolved["errors"]:
        result["errors"] += resolved["errors"]
        return {**result, "status": "unsatisfied"}
    content = mergeplan.render(resolved)
    result["merge_plan"]["content"] = content
    result["merge_plan"]["rows"] = mergeplan.rows_output(resolved, ref["owner"], ref["repo"])
    issue, failure = bodies.fetch_issue(ref)
    if failure:
        return failed(failure)
    composed = compose_checked(issue["body"], target["kind"], parsed["closing"], content)
    if issue["sha256"] != target["sha256"]:
        # 本文が計画案を作ったときと違うのは、書き込み済みのときか、_plan で本文を読んだ後に本文が変わったとき
        if "error" in composed or composed["body"] != issue["body"]:
            result["errors"].append({"line": None, "message": f"{ref['key']} の本文が、計画案を作ったときから変わった (計画案を直す)"})
            return {**result, "status": "unsatisfied"}
    elif "error" in composed:
        # _plan が同じ本文で組み立てられることを確認しているので、この分岐は実行されない
        result["errors"].append({"line": None, "message": f"{ref['key']} の本文に書き込めない: {composed['error']}"})
        return {**result, "status": "unsatisfied"}
    else:
        written = bodies.write_body(issue["url"], composed["body"])
        if gh.failed(written):
            return failed(written)
        result["done"].append({"key": None, "action": "write-body", "url": issue["url"]})
    result["body_state"] = "applied"
    if not result["approval_recorded"]:
        line = records.format_line("approval", {"draft": parsed["file_name"]}, where="comment")["line"]
        r = gh.run(["issue", "comment", issue["url"], "--body-file", "-"], mutation=True,
                   stdin=f"{line}\n\n{APPROVAL_TEXT.format(file_name=parsed['file_name'])}\n")
        if gh.failed(r):
            return failed(r)
        result["done"].append({"key": None, "action": "record-approval", "url": issue["url"]})
        result["approval_recorded"] = True
    return result
