    nodes = ((meta.get("blocking") or {}).get("nodes")) or []
    return [{"number": n.get("number"), "url": n.get("url"), "title": n.get("title"), "state": n.get("state")}
            for n in nodes if isinstance(n, dict) and n.get("state") == "OPEN"]


def _milestone(meta):
    return (meta.get("milestone") or {}).get("title")


def _items_text(items):
    return [{"group": item["group"], "text": item["text"]} for item in items]


def common_items(items):
    """管理 Issue のチェックボックスのうち、節「すべての作業 Issue に共通するクローズ条件」の項目。"""
    return [item for item in items if item["heading"] == COMMON_HEADING]


def copy_items(items):
    """作業 Issue のチェックボックスのうち、共通の条件のコピーの見出しの下の項目。"""
    return [item for item in items if item["heading"] and COPY_HEADING_RE.match(item["heading"])]


def _new_result(ref, role, managing_ref):
    return {"status": "ok", "issue": ref["key"], "url": None, "role": role,
            "managing": managing_ref["key"] if managing_ref else None, "satisfied": False, "unsatisfied": [],
            "evidence": [], "pr": None, "checkboxes": None, "work_issues": [], "blocking": [], "errors": []}


def _unsatisfied(result, kind, message, line=None, url=None):
    result["unsatisfied"].append({"kind": kind, "message": message, "line": line, "url": url})


def _check_pr(result, cell, base, kind, owner, repo):
    if not cell:
        _unsatisfied(result, kind, "PR マージ計画の表に PR が無い" if kind == "pr" else "設定「管理 Issue の PR」に PR が無い")
        return
    url = mergeplan.pr_url(cell, owner, repo)
    data = _need(fetch_pr(url))
    merged = pr_merged(data)
    info = {"url": data["url"], "state": data.get("state"), "merged": merged, "base": data.get("baseRefName")}
    if kind == "pr":
        result["pr"] = info
    else:
        result["managing_pr"] = info
    if not merged:
        _unsatisfied(result, kind, f"PR がマージされていない (状態: {data.get('state')})", url=data["url"])
    elif data.get("baseRefName") != base:
        _unsatisfied(result, kind, f"PR のマージ先 {data.get('baseRefName')} が、PR マージ計画のマージ先 {base} と違う",
                     url=data["url"])
    else:
        result["evidence"].append(data["url"])


def _check_checkboxes(result, body, exclude_common=False):
    parsed = checkboxes.parse(body)
    if "error" in parsed:
        result["errors"].append(parsed["error"])
        return None
    items = [i for i in parsed["items"] if not (exclude_common and i["heading"] == COMMON_HEADING)]
    if not items:
        result["errors"].append("節「クローズ条件」にチェックボックスが無い")
    for item in items:
        if item["state"] in checkboxes.SATISFIED:
            result["evidence"].append(item["evidence"] or item["carved_out"])
        else:
            _unsatisfied(result, "checkbox", f"{item['state']}: {item['text']}", line=item["line"])
    result["checkboxes"] = checkboxes.summarize(items)
    return parsed["items"]


def _read_plan(result, body, name):
    plan = mergeplan.read_region(body)
    if "error" in plan:
        result["errors"].append(f"{name}の PR マージ計画: {plan['error']}")
        return None
    if plan["errors"]:
        result["errors"] += [f"{name}の PR マージ計画: 行 {e['line']}: {e['message']}" if e["line"] else
                             f"{name}の PR マージ計画: {e['message']}" for e in plan["errors"]]
        return None
    return plan


def _row_of(plan, number):
    return next((row for row in plan["rows"] if row["work"]["number"] == number), None)


def _check_working(result, ref, issue, meta, items, managing_ref):
    managing = _need(bodies.fetch_issue(managing_ref))
    managing_meta = _need(fetch_meta(managing_ref))
    plan = _read_plan(result, managing["body"], "管理 Issue ")
    if plan is not None:
        if f"{ref['owner']}/{ref['repo']}".lower() != f"{managing_ref['owner']}/{managing_ref['repo']}".lower():
            result["errors"].append("作業 Issue が管理 Issue と別のリポジトリにある (PR マージ計画の表は #番号 で書くため)")
        else:
            row = _row_of(plan, ref["number"])
            if row is None:
                result["errors"].append(f"管理 Issue の PR マージ計画の表に、作業 Issue #{ref['number']} の行が無い")
            else:
                _check_pr(result, row["pr"], row["base"], "pr", managing_ref["owner"], managing_ref["repo"])
    managing_parsed = checkboxes.parse(managing["body"])
    if "error" in managing_parsed:
        result["errors"].append(f"管理 Issue のクローズ条件: {managing_parsed['error']}")
    elif items is not None:
        expected = _items_text(common_items(managing_parsed["items"]))
        actual = _items_text(copy_items(items))
        if expected != actual:
            _unsatisfied(result, "common", "共通の条件のコピーが、管理 Issue の節「" + COMMON_HEADING + "」と違う",
                         url=managing["url"])
    if _milestone(meta) != _milestone(managing_meta):
        _unsatisfied(result, "milestone", f"マイルストーン {_milestone(meta)!r} が、管理 Issue のマイルストーン "
                                          f"{_milestone(managing_meta)!r} と違う", url=issue["url"])


def _check_managing(result, ref, issue):
    plan = _read_plan(result, issue["body"], "")
    if plan is None:
        return
    for row in plan["rows"]:
        work_ref = refs.parse_ref(f"#{row['work']['number']}", default_repo=f"{ref['owner']}/{ref['repo']}")
        work = _need(fetch_meta(work_ref))
        result["work_issues"].append({"number": work.get("number"), "url": work["url"], "state": work.get("state")})
        if work.get("state") != "CLOSED":
            _unsatisfied(result, "work-issue", f"作業 Issue #{row['work']['number']} が閉じていない", url=work["url"])
    settings = plan["settings"]
    if settings["config"] in ("2", "3"):
        result["managing_pr"] = None
        _check_pr(result, settings["managing_pr"], settings["managing_base"], "managing-pr", ref["owner"], ref["repo"])


def _check_self(result, ref, issue):
    plan = _read_plan(result, issue["body"], "")
    if plan is None:
        return
    if len(plan["rows"]) != 1 or plan["rows"][0]["work"]["number"] != ref["number"]:
        result["errors"].append(f"自己管理 Issue の PR マージ計画の表は、この Issue (#{ref['number']}) の 1 行だけにする")
        return
    row = plan["rows"][0]
    _check_pr(result, row["pr"], row["base"], "pr", ref["owner"], ref["repo"])


def check(ref, role, managing_ref=None):
    """閉じる前の検査。role は ROLES のどれか。role が working なら managing_ref (管理 Issue の参照) が要る。

    返り値は {"status" (ok・unsatisfied・gh_failed), "issue", "url", "role", "managing", "satisfied", "unsatisfied"
    ({"kind", "message", "line", "url"} の配列), "evidence" (根拠の URL の配列。同じ URL は現れた順に 1 回だけ), "pr", "checkboxes", "work_issues",
    "blocking", "errors"} (gh_failed では "gh_error" も持つ)。
    """
    result = _new_result(ref, role, managing_ref)
    try:
        issue = _need(bodies.fetch_issue(ref))
        result["url"] = issue["url"]
        meta = _need(fetch_meta(ref))
        result["blocking"] = open_blocking(meta)
        items = _check_checkboxes(result, issue["body"], exclude_common=(role == "managing"))
        if role == "working":
            _check_working(result, ref, issue, meta, items, managing_ref)
        elif role == "managing":
            _check_managing(result, ref, issue)
        else:
            _check_self(result, ref, issue)
    except _GhFailed as e:
        return {**result, "status": "gh_failed", "gh_error": e.result}
    result["evidence"] = list(dict.fromkeys(result["evidence"]))
    result["satisfied"] = not result["unsatisfied"] and not result["errors"]
    result["status"] = "ok" if result["satisfied"] else "unsatisfied"
    return result


def common_copies(managing_ref):
    """管理 Issue の共通の条件と、開いている作業 Issue (PR マージ計画の表の行) のコピーを比べる。

    返り値は {"status", "issue", "url", "common" (管理 Issue の共通の項目), "outdated" ({"number", "url", "expected",
    "actual"} の配列), "up_to_date", "skipped" (閉じた作業 Issue), "errors"}。
    """
    result = {"status": "ok", "issue": managing_ref["key"], "url": None, "common": [], "outdated": [], "up_to_date": [],
              "skipped": [], "errors": []}
    try:
        managing = _need(bodies.fetch_issue(managing_ref))
        result["url"] = managing["url"]
        plan = _read_plan(result, managing["body"], "")
        parsed = checkboxes.parse(managing["body"])
        if "error" in parsed:
            result["errors"].append(parsed["error"])
        if plan is None or "error" in parsed:
            result["status"] = "unsatisfied"
            return result
        expected = _items_text(common_items(parsed["items"]))
        result["common"] = expected
        for row in plan["rows"]:
            work_ref = refs.parse_ref(f"#{row['work']['number']}", default_repo=f"{managing_ref['owner']}/{managing_ref['repo']}")
            work = _need(bodies.fetch_issue(work_ref))
            entry = {"number": work["number"], "url": work["url"]}
            if work["state"] != "OPEN":
                result["skipped"].append(entry)
                continue
            work_parsed = checkboxes.parse(work["body"])
            actual = [] if "error" in work_parsed else _items_text(copy_items(work_parsed["items"]))
            if actual != expected:
                result["outdated"].append({**entry, "expected": expected, "actual": actual})
            else:
                result["up_to_date"].append(entry)
    except _GhFailed as e:
        return {**result, "status": "gh_failed", "gh_error": e.result}
    result["status"] = "unsatisfied" if result["outdated"] or result["errors"] else "ok"
    return result


# --- 依存先が片付いたこと (R50) ----------------------------------------------------------------------------------

def _reference_patterns(closed_ref, base_repo):
    owner_repo = f"{closed_ref['owner']}/{closed_ref['repo']}"
    patterns = [re.escape(f"https://github.com/{owner_repo}/issues/{closed_ref['number']}") + r"(?![0-9])",
                r"(?<![\w/.-])" + re.escape(f"{owner_repo}#{closed_ref['number']}") + r"(?![0-9])"]
    if base_repo.lower() == owner_repo.lower():
        patterns.append(r"(?<![\w/])#" + str(closed_ref["number"]) + r"(?![0-9])")
    return [re.compile(p, re.IGNORECASE) for p in patterns]


def remove_dependency(body, closed_ref, base_repo):
    """本文の節「依存先」から、閉じた Issue (closed_ref) を指す箇条書きの項目を消す。base_repo は本文の Issue のリポジトリ。

    項目は、行頭の箇条書きの行と、その下の字下げした行。閉じた Issue の URL か `owner/repo#番号` を含む項目と、
    base_repo が閉じた Issue と同じリポジトリなら `#番号` を含む項目を消す。項目が無くなったら、節ごと消す。
    返り値は {"body", "removed" (消した行の配列), "section_removed"}。節が無ければ本文を変えずに返す。
    """
    section = bodies.find_section(body, DEPENDENCIES_SECTION)
    if "error" in section:
        return {"body": body, "removed": [], "section_removed": False}
    lines = bodies.split_lines(body)
    start, end = section["heading_line"] - 1, section["end_line"]
    patterns = _reference_patterns(closed_ref, base_repo)
    blocks, i = [], start + 1
    while i < end:
        if _LIST_ITEM_RE.match(lines[i]):
            j = i + 1
            while j < end and lines[j].strip() and lines[j][:1] in (" ", "\t"):
                j += 1
            blocks.append((i, j))
            i = j
            continue
        i += 1
    remove = [(a, b) for a, b in blocks if any(p.search(lines[a]) for p in patterns)]
    if not remove:
        return {"body": body, "removed": [], "section_removed": False}
    removed = [lines[k].rstrip("\r") for a, b in remove for k in range(a, b)]
    if len(remove) == len(blocks):
        new_lines = lines[:start] + lines[end:]
        return {"body": "\n".join(new_lines), "removed": removed, "section_removed": True}
    drop = {k for a, b in remove for k in range(a, b)}
    new_lines = [line for k, line in enumerate(lines) if k not in drop]
    return {"body": "\n".join(new_lines), "removed": removed, "section_removed": False}


def _issue_value(closed_ref, dependent_ref):
    if f"{closed_ref['owner']}/{closed_ref['repo']}".lower() == f"{dependent_ref['owner']}/{dependent_ref['repo']}".lower():
        return f"#{closed_ref['number']}"
    return closed_ref["key"]


RESOLVED_TEXT = "依存先の Issue {url} が閉じた。"
REMOVED_TEXT = "この Issue の節「依存先」から、その項目を消した。"


def dependents_plan(ref):
    """閉じる Issue (ref) を依存先とする開いた Issue への書き込みを示す (示す)。GitHub には書き込まない。

    返り値は {"status", "issue", "url", "state", "dependents" ({"number", "url", "sha256", "actions", "new_body"} の配列),
    "errors"}。actions は {"action": "comment", "line"} と {"action": "edit-dependencies", "removed", "section_removed"}。
    """
    result = {"status": "ok", "issue": ref["key"], "url": None, "state": None, "dependents": [], "errors": []}
    try:
        meta = _need(fetch_meta(ref))
        result.update(url=meta["url"], state=meta.get("state"))
        for node in open_blocking(meta):
            dependent_ref = refs.parse_ref(node["url"])
            dependent = _need(bodies.fetch_issue(dependent_ref))
            listed = _need(records.list_records(dependent_ref))
            value = _issue_value(ref, dependent_ref)
            base_repo = f"{dependent_ref['owner']}/{dependent_ref['repo']}"
            recorded = any(r["kind"] == "dependency-resolved"
                           and refs.same_issue(refs.parse_ref(r["values"]["issue"], default_repo=base_repo), ref)
                           for r in listed["records"])
            actions = []
            if not recorded:
                actions.append({"action": "comment",
                                "line": records.format_line("dependency-resolved", {"issue": value}, where="comment")["line"]})
            removed = remove_dependency(dependent["body"], ref, base_repo)
            if removed["removed"]:
                actions.append({"action": "edit-dependencies", "removed": removed["removed"],
                                "section_removed": removed["section_removed"]})
            result["dependents"].append({"number": dependent["number"], "url": dependent["url"],
                                         "sha256": dependent["sha256"], "actions": actions, "new_body": removed["body"]})
    except _GhFailed as e:
        return {**result, "status": "gh_failed", "gh_error": e.result}
    return result


def dependents_resolve(ref):
    """dependents_plan の書き込みを行う (実行する)。ref が閉じていなければ書かない。

    返り値は dependents_plan の辞書に {"done" ({"number", "action", "url"} の配列)} を足したもの。gh が失敗したら、そこで
    止めて status を gh_failed にし、それまでの書き込みを done に入れる。もう一度実行すると、書いた記録と消した項目は
    書かない。
    """
    result = dependents_plan(ref)
    result["done"] = []
    if result["status"] != "ok":
        return result
    if result["state"] != "CLOSED":
        result["errors"].append(f"{ref['key']} が閉じていない (閉じてから実行する)")
        result["status"] = "unsatisfied"
        return result
    for dependent in result["dependents"]:
        edited = any(a["action"] == "edit-dependencies" for a in dependent["actions"])
        for action in dependent["actions"]:
            if action["action"] == "comment":
                text = RESOLVED_TEXT.format(url=result["url"]) + (REMOVED_TEXT if edited else "")
                r = gh.run(["issue", "comment", dependent["url"], "--body-file", "-"], mutation=True,
                           stdin=f"{action['line']}\n\n{text}\n")
            else:
                r = bodies.write_body(dependent["url"], dependent["new_body"])
            if gh.failed(r):
                return {**result, "status": "gh_failed", "gh_error": r}
            result["done"].append({"number": dependent["number"], "action": action["action"], "url": dependent["url"]})
    return result

def _pr_url(value):
    parsed = refs.parse_ref(value)
    if "error" in parsed or parsed["kind"] != "pull":
        return "PR の URL (https://github.com/<owner>/<repo>/pull/<番号>)"
    return None


# キーごとの値の検査。値が形どおりなら None、違えば期待する形の説明を返す
KEYS = {
    "role": _enum(ROLES),
    "session": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "previous": _pattern(_SESSION_RE, "英数字で始まり、英数字・_・.・- が続くセッションの ID"),
    "branch": _branch,
    "draft": _draft,
    "type": _enum(REPORT_TYPES),
    "pr": _pr_url,
    "date": _date,
    "old": _issue,
    "issue": _issue,
    "result": _enum(RESULTS),
    "key": _pattern(_KEY_RE, "英数字で始まり、英数字・.・_・- が続くキー"),
}


def _check(kind, values, where):
    """種類と値を検査し、誤りの配列を返す。"""
    errors = []
    spec = KINDS.get(kind)
    if spec is None:
        return [f"知らない種類: {kind!r}"]
    if where is not None and spec["where"] != where:
        place = "Issue の本文の末尾の行" if spec["where"] == "body" else "記録のコメントの 1 行目"
        errors.append(f"種類 {kind} は{place}だけで使う")
    allowed = spec["required"] + spec["optional"]
    for key in values:
        if key not in allowed:
            errors.append(f"種類 {kind} に知らないキー: {key!r} (書けるキー: {', '.join(allowed) or 'なし'})")
    for key in spec["required"]:
        if key not in values:
            errors.append(f"種類 {kind} の必須のキーが無い: {key}")
    for key, value in values.items():
        if key not in allowed:
            continue
        if not value or any(c.isspace() for c in value):
            errors.append(f"キー {key} の値が空か、空白を含む")
            continue
        problem = KEYS[key](value)
        if problem:
            errors.append(f"キー {key} の値 {value!r} が {problem} ではない")
    return errors


def format_line(kind, values, where=None):
    """1 行目を作る。values はキーと値の辞書。返り値は {"line"} か {"errors"}。キーは KINDS の順に並べる。"""
    errors = _check(kind, values, where)
    if errors:
        return {"errors": errors}
    spec = KINDS[kind]
    parts = [PREFIX, kind] + [f"{key}={values[key]}" for key in spec["required"] + spec["optional"] if key in values]
    return {"line": " ".join(parts)}


def is_record_line(line):
    return (line or "").startswith(PREFIX)


def parse_line(line, where=None):
    """1 行目を解析する。返り値は {"kind", "values"} か {"errors"}。where を渡すと、その場所で使える種類かも検査する。"""
    line = (line or "").rstrip("\r")
    if not is_record_line(line):
        return {"errors": [f"{PREFIX} で始まらない"]}
    tokens = line[len(PREFIX):].split()
    if not tokens:
        return {"errors": ["種類が無い"]}
    kind, errors, values = tokens[0], [], {}
    if not _KIND_RE.match(kind):
        return {"errors": [f"種類の形ではない: {kind!r}"]}
    for token in tokens[1:]:
        m = _PAIR_RE.match(token)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {token!r}")
            continue
        if m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
            continue
        values[m.group("key")] = m.group("value")
    errors += _check(kind, values, where)
    if errors:
        return {"errors": errors}
    return {"kind": kind, "values": values}


def parse_assignments(items):
    """`<キー>=<値>` の文字列の配列を辞書にする。返り値は ({キー: 値}, 誤りの配列)。"""
    values, errors = {}, []
    for item in items:
        m = _PAIR_RE.match(item)
        if not m:
            errors.append(f"<キー>=<値> の形ではない: {item!r}")
        elif m.group("key") in values:
            errors.append(f"同じキーが 2 回ある: {m.group('key')}")
        else:
            values[m.group("key")] = m.group("value")
    return values, errors


def _split_body(body):
    first, _, rest = (body or "").partition("\n")
    return first.rstrip("\r"), rest.lstrip("\r\n")


def collect(comments, login):
    """コメントの配列 (REST の issue comment の形) から記録を集める。

    投稿者 (user.login) が login と違うコメントと、1 行目が PREFIX で始まらないコメントは除く。ログインは大文字と小文字を
    区別しない。返り値は {"records", "invalid", "skipped_other_authors"}。records の要素は
    {"kind", "values", "id", "url", "created_at", "updated_at", "body"} (body は 1 行目と続く空行を除いた本文)、
    invalid の要素は {"id", "url", "line", "errors"}。
    """
    records, invalid, skipped = [], [], 0
    for comment in comments:
        author = ((comment.get("user") or {}).get("login") or "")
        if author.lower() != (login or "").lower():
            if is_record_line(_split_body(comment.get("body"))[0]):
                skipped += 1
            continue
        first, rest = _split_body(comment.get("body"))
        if not is_record_line(first):
            continue
        parsed = parse_line(first, where="comment")
        base = {"id": comment.get("id"), "url": comment.get("html_url")}
        if "errors" in parsed:
            invalid.append({**base, "line": first, "errors": parsed["errors"]})
            continue
        records.append({"kind": parsed["kind"], "values": parsed["values"], **base,
                        "created_at": comment.get("created_at"), "updated_at": comment.get("updated_at"), "body": rest})
    return {"records": records, "invalid": invalid, "skipped_other_authors": skipped}


def fetch_comments(ref):
    """Issue (か PR) のコメントを、投稿の順に全部読む。返り値は (コメントの配列, None) か (None, 失敗した gh の結果)。"""
    result = gh.run(["api", f"repos/{ref['owner']}/{ref['repo']}/issues/{ref['number']}/comments", "--paginate", "--slurp"],
                    expect_json=True)
    if gh.failed(result):
        return None, result
    pages = result["json"]
    if not isinstance(pages, list) or not all(isinstance(p, list) for p in pages):
        return None, {**result, "json_error": "応答がページの配列 (--slurp の形) ではない"}
    return [c for page in pages for c in page if isinstance(c, dict)], None


def list_records(ref):
    """Issue の記録を集める。返り値は ({"login", "records", "invalid", "skipped_other_authors"}, None) か
    (None, 失敗した gh の結果)。"""
    login, failure = gh.viewer_login()
    if failure:
        return None, failure
    comments, failure = fetch_comments(ref)
    if failure:
        return None, failure
    return {"login": login, **collect(comments, login)}, None


# --- 動いている作業セッション (計画の R29・KTD17) -------------------------------------------------------------

STATE_FIELDS = "number,url,state"

# 記録のコメント session の本文で、セッションの名前を書く行 (形は文書 references/start-instruction.md の節「起動の後の記録」)
SESSION_NAME_RE = re.compile(r"^- (?:作業|管理)セッションの名前: (?P<name>\S.*)$", re.MULTILINE)


def session_name(body):
    """記録のコメント session の本文から、セッションの名前を読む。名前の行が無ければ None。"""
    m = SESSION_NAME_RE.search(body or "")
    return m.group("name").strip() if m else None


def fetch_state(ref):
    """Issue の番号・URL・状態を読む。返り値は (辞書, None) か (None, 失敗した gh の結果)。"""
    result = gh.run(["issue", "view", str(ref["number"]), "-R", f"{ref['owner']}/{ref['repo']}", "--json", STATE_FIELDS],
                    expect_json=True)
    if gh.failed(result):
        return None, result
    data = result["json"]
    if not isinstance(data, dict) or not isinstance(data.get("state"), str):
        return None, {**result, "json_error": "応答に state が無い"}
    return data, None


def _session_entry(record):
    return {"session": record["values"]["session"], "previous": record["values"].get("previous"),
            "branch": record["values"].get("branch"), "name": session_name(record["body"]), "record_url": record["url"]}


def active_sessions(managing_ref, work_numbers):
    """管理 Issue の管理セッションと、作業 Issue (番号の配列) の動いている作業セッションを、記録のコメントから集める。

    作業 Issue ごとに、最後の session の記録 (role=working) を使う。閉じた作業 Issue・session の記録が無い作業 Issue・
    最後の session の記録と同じセッションの abandon の記録がある作業 Issue は除く。
    返り値は ({"managing", "sessions", "excluded"}, None) か (None, 失敗した gh の結果)。managing は管理 Issue の最後の
    session の記録 (role=managing) {"session", "previous", "branch", "name", "record_url"} か None。sessions の要素は
    {"number", "url", "session", "previous", "branch", "name", "record_url"}、excluded の要素は {"number", "url", "reason"}
    (reason は closed・no-session・abandoned)。
    """
    result = {"managing": None, "sessions": [], "excluded": []}
    listed, failure = list_records(managing_ref)
    if failure:
        return None, failure
    managing = [r for r in listed["records"] if r["kind"] == "session" and r["values"]["role"] == "managing"]
    if managing:
        result["managing"] = _session_entry(managing[-1])
    repo = f"{managing_ref['owner']}/{managing_ref['repo']}"
    for number in work_numbers:
        ref = refs.parse_ref(f"#{number}", default_repo=repo)
        state, failure = fetch_state(ref)
        if failure:
            return None, failure
        base = {"number": number, "url": state.get("url")}
        if state["state"] != "OPEN":
            result["excluded"].append({**base, "reason": "closed"})
            continue
        listed, failure = list_records(ref)
        if failure:
            return None, failure
        sessions = [r for r in listed["records"] if r["kind"] == "session" and r["values"]["role"] == "working"]
        if not sessions:
            result["excluded"].append({**base, "reason": "no-session"})
            continue
        latest = _session_entry(sessions[-1])
        if any(r["kind"] == "abandon" and r["values"]["session"] == latest["session"] for r in listed["records"]):
            result["excluded"].append({**base, "reason": "abandoned"})
            continue
        result["sessions"].append({**base, **latest})
    return result, None
"""Issue の本文の読み書き。マークで囲んだ範囲と見出しの節の取り出し・範囲の書き換え・本文のハッシュ値 (計画の KTD7・KTD8)。

マークは HTML のコメントで、範囲の名前ごとに開始と終了の 2 行を書く。

    <!-- issue-practice:<名前> -->
    ...
    <!-- /issue-practice:<名前> -->

範囲の名前は定数 REGIONS にあるものだけ (文書 `issue-practice/references/closing-conditions.md` の節「節の場所」と一致させる)。
マークは、その行にマークだけがある行として書く。コードブロック (``` か ~~~ で囲んだ部分) の中のマークと見出しは数えない。
本文に書式の例を書いたときに、例を範囲や節と取り違えないため。

関数は、解析できた値の辞書か、理由の文字列を持つ辞書 (`{"error": <理由>}`) を返す。例外は送出しない。
"""

import hashlib
import re

from issue_practice import gh

REGIONS = ("closing-conditions", "merge-plan")

_FENCE_RE = re.compile(r"^ {0,3}(```|~~~)")
_HEADING_RE = re.compile(r"^(#{1,6}) +(.*?)\s*#*\s*$")


def start_mark(name):
    return f"<!-- issue-practice:{name} -->"


def end_mark(name):
    return f"<!-- /issue-practice:{name} -->"


def body_sha256(body):
    """本文のハッシュ値 (UTF-8 の SHA-256 の 16 進数)。本文は gh が返したまま使い、改行や空白をそろえない。"""
    return hashlib.sha256((body or "").encode("utf-8")).hexdigest()


def split_lines(body):
    """本文を行に分ける。改行は `\\n` で分け、行末の `\\r` は残す (書き戻したときに元の本文に戻るように)。"""
    return (body or "").split("\n")


def outside_fences(lines):
    """コードブロックの外にある行の番号 (0 から数える) の集合。"""
    result = set()
    fence = None
    for i, line in enumerate(lines):
        m = _FENCE_RE.match(line)
        if m:
            marker = m.group(1)
            if fence is None:
                fence = marker
                continue
            if marker == fence:
                fence = None
                continue
        if fence is None:
            result.add(i)
    new_lines = lines[:start + 1] + [""] + inner + [""] + lines[end:]
    return {"body": "\n".join(new_lines)}


def find_section(body, title, level=2):
    """見出し (レベル level、文字列 title) の節を探す。節は、次の同じレベル以上の見出しの手前まで。

    返り値は {"title", "heading_line", "end_line", "content", "lines"} か {"error"}。end_line は節の最後の行。
    """
    lines = split_lines(body)
    visible = outside_fences(lines)
    found = [i for i in sorted(visible) if heading(lines[i]) == (level, title)]
    if not found:
        return {"error": f"節「{title}」(見出しのレベル {level}) が無い"}
    if len(found) > 1:
        return {"error": f"節「{title}」が複数ある (行 {', '.join(str(i + 1) for i in found)})"}
    start = found[0]
    end = len(lines)
    for i in sorted(visible):
        if i <= start:
            continue
        h = heading(lines[i])
        if h and h[0] <= level:
            end = i
            break
    inner = [(i + 1, lines[i].rstrip("\r")) for i in range(start + 1, end)]
    content = "\n".join(_strip_blank([text for _, text in inner]))
    return {"title": title, "heading_line": start + 1, "end_line": end, "content": content, "lines": inner}


def write_body(url, body):
    """Issue の本文を body に書き換える (`gh issue edit <URL> --body-file -`)。返り値は gh.run の結果。

    書く前に本文が読んだときから変わっていないかを確認するのは、呼び出し元 (計画の KTD7)。
    """
    return gh.run(["issue", "edit", url, "--body-file", "-"], mutation=True, stdin=body)


ISSUE_FIELDS = "number,url,state,title,body,updatedAt"


def fetch_issue(ref):
    """Issue を gh で読む。ref は refs.parse_ref の結果で、key が決まっているもの。

    返り値は ({"number", "url", "state", "title", "body", "updated_at", "sha256"}, None) か、(None, 失敗した gh の結果)。
    """
    result = gh.run(["issue", "view", str(ref["number"]), "-R", f"{ref['owner']}/{ref['repo']}", "--json", ISSUE_FIELDS],
                    expect_json=True)
    if gh.failed(result):
        return None, result
    data = result["json"]
    if not isinstance(data, dict) or not isinstance(data.get("body"), str):
        return None, {**result, "json_error": "応答に本文 (body) が無い"}
    issue = {"number": data.get("number"), "url": data.get("url"), "state": data.get("state"), "title": data.get("title"),
             "body": data["body"], "updated_at": data.get("updatedAt"), "sha256": body_sha256(data["body"])}
    return issue, None
"""計画案のファイルの共通の部分。保存先の確認・ファイル名・先頭の書式の解析・本文の照合 (計画の KTD7・KTD13・KTD14)。

書式の SSOT は、文書 `issue-practice/references/draft-plan.md` とこのモジュール。計画案の中身 (スキルごとの節) は扱わない。
関数は、解析できた値の辞書か、理由を持つ辞書を返す。例外は送出しない (ファイルを開けないときの OSError を除く)。
"""

import os
import re
import subprocess

from issue_practice import bodies, refs

DRAFT_DIR = "tmp/issue-practice"

# プラグイン issue-practice のスキルの名前 (計画の KD3)。ファイル名の <スキル名> はこのどれか
SKILLS = (
    "new-issue",
    "managing-issue-plan",
    "managing-issue-run",
    "managing-issue-close",
    "working-issue",
    "release-plan",
    "release-issue-plan",
    "release-run",
    "release-close",
)

TARGET_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
FILENAME_RE = re.compile(r"^(?P<date>[0-9]{8})-(?P<time>[0-9]{4})-(?P<rest>[a-z0-9][a-z0-9-]*)\.md$")
TITLE_RE = re.compile(r"^# 計画案: (?P<title>\S.*)$")
SOURCES_HEADING = "元にした Issue"
SOURCE_RE = re.compile(r"^- (?P<url>\S+) 本文の SHA-256: (?P<sha256>[0-9a-f]{64})$")
NONE_ITEM = "- なし"

# git を実行するときに消す環境変数。--root で渡したリポジトリだけを基準にするため (hook の中などで GIT_DIR が設定されていても)
_GIT_ENV_KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_COMMON_DIR", "GIT_PREFIX")


def parse_file_name(name):
    """ファイル名を解析する。返り値は {"date", "time", "skill", "target"} か {"error"}。"""


def parse(text, name):
    """計画案の先頭の書式を解析する。name はファイル名 (ディレクトリを含まない)。

    返り値は {"file_name", "title", "skill", "target", "created", "sources", "sections", "errors"}。errors は
    {"line" (1 から数える行番号。行に結び付かない誤りは null), "message"} の配列で、空なら形どおり。
    sources は {"issue" (owner/repo#番号), "url", "sha256", "line"} の配列、sections は節「元にした Issue」の後の
    レベル 2 の節 {"title", "line"} の配列。
    """
    errors = []
    result = {"file_name": name, "title": None, "skill": None, "target": None, "created": None, "sources": [],
              "sections": [], "errors": errors}
    parsed_name = parse_file_name(name)
    if "error" in parsed_name:
        errors.append({"line": None, "message": parsed_name["error"]})
    else:
        result.update(skill=parsed_name["skill"], target=parsed_name["target"],
                      created=f"{parsed_name['date'][:4]}-{parsed_name['date'][4:6]}-{parsed_name['date'][6:]} "
                              f"{parsed_name['time'][:2]}:{parsed_name['time'][2:]}")
    lines = bodies.split_lines(text)
    visible = bodies.outside_fences(lines)
    m = TITLE_RE.match(lines[0].rstrip("\r")) if lines else None
    if not m:
        errors.append({"line": 1, "message": "1 行目が「# 計画案: <題>」ではない"})
    else:
        result["title"] = m.group("title").strip()
    level2 = [(i, bodies.heading(lines[i])[1]) for i in sorted(visible)
              if bodies.heading(lines[i]) and bodies.heading(lines[i])[0] == 2]
    source_headings = [i for i, title in level2 if title == SOURCES_HEADING]
    if not source_headings:
        errors.append({"line": None, "message": f"節「{SOURCES_HEADING}」(## {SOURCES_HEADING}) が無い"})
        return result
    if len(source_headings) > 1:
        errors.append({"line": source_headings[1] + 1, "message": f"節「{SOURCES_HEADING}」が複数ある"})
    start = source_headings[0]
    if level2[0][0] != start:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」が最初のレベル 2 の見出しではない"})
    following = [i for i, _ in level2 if i > start]
    end = following[0] if following else len(lines)
    result["sections"] = [{"title": title, "line": i + 1} for i, title in level2 if i > start]
    items, has_none, seen = [], False, {}
    for i in range(start + 1, end):
        line = lines[i].rstrip("\r")
        if not line.strip():
            continue
        if line == NONE_ITEM:
            has_none = True
            items.append(i)
            continue
        sm = SOURCE_RE.match(line)
        if not sm:
            errors.append({"line": i + 1, "message": "「- <Issue の URL> 本文の SHA-256: <64 桁の 16 進数>」か「- なし」ではない"})
            continue
        ref = refs.parse_ref(sm.group("url"))
        if "error" in ref or not sm.group("url").startswith("https://"):
            errors.append({"line": i + 1, "message": f"Issue か PR の URL ではない: {sm.group('url')}"})
            continue
        key = ref["key"].lower()
        if key in seen:
            errors.append({"line": i + 1, "message": f"同じ Issue が 2 回ある (行 {seen[key]})"})
            continue
        seen[key] = i + 1
        items.append(i)
        result["sources"].append({"issue": ref["key"], "url": ref["url"], "sha256": sm.group("sha256"), "line": i + 1})
    if not items:
        errors.append({"line": start + 1, "message": f"節「{SOURCES_HEADING}」に項目が無い (無ければ「- なし」と書く)"})
    elif has_none and result["sources"]:
        errors.append({"line": start + 1, "message": "「- なし」と Issue の項目が両方ある"})
    return result


def read(path):
    """計画案のファイルを読んで parse する。ファイルを開けなければ OSError を送出する。"""
    with open(path, encoding="utf-8") as f:
        text = f.read()
    return parse(text, os.path.basename(path))


def compare(sources):
    """節「元にした Issue」の Issue の本文を再度読み込み、ハッシュ値を比べる。

    返り値は {"results": [{"issue", "url", "sha256_draft", "sha256_now", "changed", "updated_at"}], "gh_error"}。
    gh が失敗したら、そこで止めて gh_error に失敗した gh の結果を入れる (残りは読まない)。
    """
    results = []
    for source in sources:
        ref = refs.parse_ref(source["url"])
        issue, failure = bodies.fetch_issue(ref)
        if failure:
            return {"results": results, "gh_error": failure}
        results.append({"issue": source["issue"], "url": source["url"], "sha256_draft": source["sha256"],
                        "sha256_now": issue["sha256"], "changed": issue["sha256"] != source["sha256"],
                        "updated_at": issue["updated_at"]})
    return {"results": results, "gh_error": None}

"""節「クローズ条件」のチェックボックスと根拠のリンクの解析 (計画の KTD9)。

書式の SSOT は、文書 `issue-practice/references/closing-conditions.md` とこのモジュール。
範囲の決め方: 本文にマーク closing-conditions が 1 つでもあればマークで囲んだ範囲 (管理 Issue)、無ければ見出し
`## クローズ条件` の節 (作業 Issue と自己管理 Issue)。

関数は、解析できた値の辞書か、理由を持つ辞書 (`{"error": <理由>}`) を返す。例外は送出しない。
"""

import re

from issue_practice import bodies

SECTION_TITLE = "クローズ条件"
REGION = "closing-conditions"

STATES = ("unchecked", "checked", "checked_without_evidence", "carved_out")
SATISFIED = ("checked", "carved_out")

_ITEM_RE = re.compile(r"^(?P<indent>[ \t]*)[-*+] \[(?P<mark>[ xX])\] (?P<text>.*)$")
_LINK_RE = re.compile(r"\s*\((?P<label>根拠|切り出し): (?P<url>https://\S+)\)\s*$")
_GROUPS = (("expected", "期待する状態"), ("verification", "確認するポイント"))


def find(body):
    """クローズ条件の範囲を決める。返り値は {"source" (region・section), "lines" ([(行番号, 行)])} か {"error"}。"""
    if bodies.has_region_mark(body, REGION):
        found = bodies.find_region(body, REGION)
        source = "region"
    else:
        found = bodies.find_section(body, SECTION_TITLE)
        source = "section"
    if "error" in found:
        return found
    return {"source": source, "lines": found["lines"]}


def _group(line):
    stripped = line.strip()
    h = bodies.heading(stripped)
    text = h[1] if h else stripped
    text = text.rstrip(":：").strip()
    for key, label in _GROUPS:
        if text == label:
            return key
    return None


def _indent_width(indent):
    return len(indent.expandtabs(4))


def parse_lines(lines):
    """範囲の行 ([(行番号, 行)]) からチェックボックスの項目を読む。コードブロックの中の行は読まない。

    返り値は項目の配列。項目は {"line", "text" (末尾のリンクを除いた文), "raw" (行のまま), "checked", "state",
    "evidence" (根拠の URL か None), "carved_out" (切り出しの URL か None), "group" (expected・verification・None),
    "heading" (直前のレベル 3 以上の見出しか None), "indent", "details" (項目の下の、より深い字下げの行の配列)}。
    """
    texts = [text for _, text in lines]
    visible = bodies.outside_fences(texts)
    items, group, heading_text, current = [], None, None, None
    for index, (number, text) in enumerate(lines):
        if index not in visible:
            continue
        m = _ITEM_RE.match(text)
        if m:
            checked = m.group("mark") != " "
            body_text = m.group("text")
            link = _LINK_RE.search(body_text)
            evidence = carved = None
            if link:
                body_text = body_text[:link.start()]
                if link.group("label") == "根拠":
                    evidence = link.group("url")
                else:
                    carved = link.group("url")
            if not checked:
                state = "unchecked"
            elif carved:
                state = "carved_out"
            elif evidence:
                state = "checked"
            else:
                state = "checked_without_evidence"
            current = {"line": number, "text": body_text.strip(), "raw": text, "checked": checked, "state": state,
                       "evidence": evidence, "carved_out": carved, "group": group, "heading": heading_text,
                       "indent": _indent_width(m.group("indent")), "details": []}
            items.append(current)
            continue
        h = bodies.heading(text)
        if h and h[0] >= 3:
            # 見出しが「期待する状態」か「確認するポイント」ならその分類、ほかの見出しなら分類をいったん無しにする
            heading_text, current, group = h[1], None, _group(text)
            continue
        g = _group(text)
        if g:
            group, current = g, None
            continue
        if current is not None and text.strip():
            if _indent_width(text[:len(text) - len(text.lstrip())]) > current["indent"]:
                current["details"].append(text.strip())
            else:
                current = None
    return items


def summarize(items):
    """項目の状態ごとの数と、満たさない項目の行番号の配列。"""
    counts = {state: 0 for state in STATES}
    for item in items:
        counts[item["state"]] += 1
    return {"counts": counts, "unsatisfied": [item["line"] for item in items if item["state"] not in SATISFIED]}


def parse(body):
    """本文のクローズ条件を読む。返り値は {"source", "items", "summary"} か {"error"}。"""
    found = find(body)
    if "error" in found:
        return found
    items = parse_lines(found["lines"])
    return {"source": found["source"], "items": items, "summary": summarize(items)}


_CHECKBOX_RE = re.compile(r"^(?P<head>[ \t]*[-*+] \[)(?P<mark>[ xX])(?P<tail>\] .*)$")
_URL_RE = re.compile(r"^https://\S+$")


def check_line(body, line, evidence=None, carved_out=None):
    """本文の line 行目 (1 から数える) のチェックボックスにチェックを入れ、末尾に `(根拠: <URL>)` か `(切り出し: <URL>)` を足す。
            result.add(i)
    return result


def heading(line):
    """見出しの行なら (レベル, 文字列)、そうでなければ None。"""
    m = _HEADING_RE.match(line.rstrip("\r"))
    if not m:
        return None
    return len(m.group(1)), m.group(2).strip()


def _strip_blank(lines):
    start, end = 0, len(lines)
    while start < end and not lines[start].strip():
        start += 1
    while end > start and not lines[end - 1].strip():
        end -= 1
    return lines[start:end]


def find_region(body, name):
    """マークで囲んだ範囲を探す。

    返り値は {"name", "start_line", "end_line", "content", "lines"} か {"error"}。行番号は本文の 1 行目を 1 とし、
    start_line と end_line はマークの行。content は範囲の中の行 (前後の空行を除く) をつないだ文字列、lines は範囲の中の行の
    配列 (行番号と行の組。前後の空行も含む)。
    """
    if name not in REGIONS:
        return {"error": f"知らない範囲の名前: {name!r} (使える名前: {', '.join(REGIONS)})"}
    lines = split_lines(body)
    visible = outside_fences(lines)
    starts = [i for i in sorted(visible) if lines[i].strip() == start_mark(name)]
    ends = [i for i in sorted(visible) if lines[i].strip() == end_mark(name)]
    if not starts and not ends:
        return {"error": f"範囲 {name} のマークが無い"}
    if len(starts) > 1:
        return {"error": f"範囲 {name} の開始のマークが複数ある (行 {', '.join(str(i + 1) for i in starts)})"}
    if len(ends) > 1:
        return {"error": f"範囲 {name} の終了のマークが複数ある (行 {', '.join(str(i + 1) for i in ends)})"}
    if not starts:
        return {"error": f"範囲 {name} の開始のマークが無い (終了のマークは行 {ends[0] + 1})"}
    if not ends:
        return {"error": f"範囲 {name} が閉じていない (開始のマークは行 {starts[0] + 1})"}
    start, end = starts[0], ends[0]
    if end < start:
        return {"error": f"範囲 {name} の終了のマーク (行 {end + 1}) が開始のマーク (行 {start + 1}) より前にある"}
    inner = [(i + 1, lines[i].rstrip("\r")) for i in range(start + 1, end)]
    content = "\n".join(_strip_blank([text for _, text in inner]))
    return {"name": name, "start_line": start + 1, "end_line": end + 1, "content": content, "lines": inner}


def has_region_mark(body, name):
    """範囲の開始か終了のマークが、コードブロックの外に 1 つでもあるか。"""
    lines = split_lines(body)
    marks = (start_mark(name), end_mark(name))
    return any(lines[i].strip() in marks for i in outside_fences(lines))


def replace_region(body, name, content):
    """マークで囲んだ範囲の中を content に書き換えた本文を返す。範囲の外は 1 文字も変えない。

    範囲の中は「開始のマーク・空行・content・空行・終了のマーク」の形にする。返り値は {"body"} か {"error"}。
    """
    found = find_region(body, name)
    if "error" in found:
        return found
    lines = split_lines(body)
    start, end = found["start_line"] - 1, found["end_line"] - 1
    inner = (content or "").strip("\n").split("\n")
    new_lines = lines[:start + 1] + [""] + inner + [""] + lines[end:]
    return {"body": "\n".join(new_lines)}


def find_section(body, title, level=2):
    """見出し (レベル level、文字列 title) の節を探す。節は、次の同じレベル以上の見出しの手前まで。
# CI のワークフロー .github/workflows/test.yml の discover ジョブが期待する、テストの対象の一覧。
# 1 行に 1 つ、「<種類> <ディレクトリ>」の形で書く。種類は python・go・node・uv のどれか。行頭の # はコメント。
# discover は追跡ファイルから実際の対象を見つけてこの一覧と比べ、差があれば失敗にする
# (見つけ方と比べ方の SSOT はワークフローの冒頭のコメント)。テストを足した・移した・消したときは、この一覧も直す。
